export const useConsumable = (gameState: GameState, playerId: number, inventoryIndex: number): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const newState = JSON.parse(JSON.stringify(gameState));
    const player = newState.players.find((p: Player) => p.id === playerId);
    if (!player || !player.inventory[inventoryIndex]) return { newState, modalInfo: null };

    const item = player.inventory[inventoryIndex] as Consumable;
    let modalInfo: ModalInfo | null = null;
    let audioAnnouncement: string | undefined;

    switch (item.effectTag) {
        case 'heal':
            const healedAmount = Math.min(player.maxHp - player.hp, item.value);
            player.hp += healedAmount;
            modalInfo = { type: 'info', title: 'Pozione Usata', message: `${player.name} recupera ${healedAmount} Volontà.` };
            audioAnnouncement = `${player.name} ha usato una ${item.name}.`;
            break;
        case 'expand_inventory':
            if (player.inventorySize < item.value) {
                player.inventorySize = item.value;
                modalInfo = { type: 'info', title: 'Inventario Ampliato', message: `La capacità del tuo inventario è ora di ${item.value} slot.` };
                audioAnnouncement = `${player.name} ha ampliato il suo inventario.`;
            } else {
                modalInfo = { type: 'info', title: 'Nessun Effetto', message: `Il tuo inventario è già più grande.` };
            }
            break;
        // 'damage_enemy' not implemented as per constants.
    }

    player.inventory.splice(inventoryIndex, 1);

    return { newState: updateCurrentGameState(newState), modalInfo, audioAnnouncement };
};

export const depositToStash = (gameState: GameState, inventoryIndex: number): GameState => {
    const newState = JSON.parse(JSON.stringify(gameState));
    const player = newState.players[newState.currentPlayerIndex];
    const stashEmptyIndex = newState.sharedStash.findIndex((slot: InventoryItem | null) => slot === null);

    if (stashEmptyIndex === -1) return newState; // Stash full

    const item = player.inventory[inventoryIndex];
    if (!item || item.type === 'questItem') return newState;

    newState.sharedStash[stashEmptyIndex] = item;
    player.inventory.splice(inventoryIndex, 1);

    return updateCurrentGameState(newState);
};

export const withdrawFromStash = (gameState: GameState, stashIndex: number): GameState => {
    const newState = JSON.parse(JSON.stringify(gameState));
    const player = newState.players[newState.currentPlayerIndex];

    if (player.inventory.length >= player.inventorySize) return newState; // Inventory full

    const item = newState.sharedStash[stashIndex];
    if (!item) return newState;

    player.inventory.push(item);
    player.hasNewItem = true;
    newState.sharedStash[stashIndex] = null;

    return updateCurrentGameState(newState);
};

