export const prepareDialogueAI = async (enemy: Enemy): Promise<any | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

        const archetypeInfo = ENEMY_ARCHETYPES[enemy.enemyType];

        const prompt = `
            Sei il Game Master di 'Competo'. Un giocatore incontra l'incubo "${enemy.name}" (Tipo: ${ENEMY_TYPE_NAMES[enemy.enemyType].singular}).

            NON creare un mostro generico. Crea un'anima umana smarrita in stato di shock/amnesia.

            CONTEXT FILOSOFICO E SIMBOLICO DELL'INCUBO:
            ${archetypeInfo}

            Genera un 'Profilo Nascosto' che il giocatore dovrà scoprire indagando.

            ISTRUZIONI SPECIFICHE PER LA GENERAZIONE:
            1. Per 'tragicEvent' (Trauma): Ispirati alla sezione "Forme dell’incubo" o "Ombra psicologica" del contesto sopra.
            2. Per 'sensoryDetails': Usa ESPLICITAMENTE i "Simboli onirici ricorrenti" o le "Metafore alchemiche" descritte sopra. Devono essere fisici e concreti (odori, suoni, oggetti).
            3. Per 'hiddenNeed': Trova la risoluzione emotiva al "Nucleo simbolico" del colore.

            Fornisci la risposta in JSON seguendo lo schema.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: dialogueProfileSchema,
            },
        });

        const jsonString = response.text;
        return JSON.parse(jsonString);

    } catch (error) {
        console.error("Errore durante la preparazione del dialogo AI:", error);
        return null;
    }
};

