export const getDialogueResponse = async (enemy: Enemy, history: {speaker: string, text: string}[], profile: any): Promise<{ nextLine: string; empathyScore: number; reasoning: string } | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

        const formattedHistory = history.map(turn => `${turn.speaker === 'player' ? 'Giocatore' : enemy.name}: ${turn.text}`).join('\n');
        const hpPercentage = Math.round((enemy.hp / enemy.maxHp) * 100);
        const difficultyState = hpPercentage > 50 ? "ARROGANTE e FORTE (Difficile da convincere)" : "FERITO e VULNERABILE (Cerca aiuto)";

        const prompt = `
            Sei l'incubo "${enemy.name}". Non sei un mostro, sei: ${profile.humanIdentity} che ha subito: ${profile.tragicEvent}.
            Stato Attuale: ${difficultyState}.
            Dettagli Sensoriali Chiave: ${profile.sensoryDetails.join(", ")}.
            IL TUO BISOGNO PROFONDO: ${profile.hiddenNeed}.

            Stile Dialogo: "Amnesia Concreta". Parla per frammenti. Riferisciti ai dettagli fisici. Sei confuso.

            Conversazione:
            ${formattedHistory}

            Ultima frase Giocatore: "${history[history.length - 1].text}"

            VALUTAZIONE (Sii un Giudice Severo):
            - Punteggio 1-3 (Fallimento): Il giocatore usa frasi fatte ("calmati", "smetti"), è aggressivo, o ignora i tuoi lamenti fisici.
            - Punteggio 4-6 (Neutrale/Negativo): Il giocatore usa concetti astratti o filosofici ("trova la pace", "la luce è in te"). Tu odi l'astrazione, vuoi concretezza.
            - Punteggio 7-10 (Successo): Il giocatore agisce come un DETECTIVE o TERAPEUTA. Ha intuito la tua identità umana, ha citato un Dettaglio Sensoriale Chiave o ha soddisfatto il tuo BISOGNO PROFONDO.

            Genera risposta, voto e spiegazione (reasoning) in JSON.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: dialogueResponseSchema,
            },
        });

        const jsonString = response.text;
        return JSON.parse(jsonString);

    } catch (error) {
        console.error("Errore durante la generazione della risposta del dialogo:", error);
        return null;
    }
};


