export const prepareDialogueAI = async (enemy: Enemy): Promise<any | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

        const archetypeInfo = ENEMY_ARCHETYPES[enemy.enemyType];

        const prompt = `
            Sei il Game Master di 'Competo'. Un giocatore incontra l'incubo "${enemy.name}" (Tipo: ${ENEMY_TYPE_NAMES[enemy.enemyType].singular}).

            NON creare un mostro generico. Crea un'anima umana smarrita in stato di shock/amnesia.

            CONTEXT FILOSOFICO E SIMBOLICO DELL'INCUBO:
            ${archetypeInfo}

            Genera un 'Profilo Nascosto' che il giocatore dovrà scoprire indagando.

            ISTRUZIONI SPECIFICHE PER LA GENERAZIONE:
            1. Per 'tragicEvent' (Trauma): Ispirati alla sezione "Forme dell’incubo" o "Ombra psicologica" del contesto sopra.
            2. Per 'sensoryDetails': Usa ESPLICITAMENTE i "Simboli onirici ricorrenti" o le "Metafore alchemiche" descritte sopra. Devono essere fisici e concreti (odori, suoni, oggetti).
            3. Per 'hiddenNeed': Trova la risoluzione emotiva al "Nucleo simbolico" del colore.
            4. Per 'initialLament': Crea una frase d'apertura suggestiva e disorientante. Massimo 20 parole.

            Fornisci la risposta in JSON seguendo lo schema.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: dialogueProfileSchema,
            },
        });

        const jsonString = response.text;
        return JSON.parse(jsonString);

    } catch (error) {
        console.error("Errore durante la preparazione del dialogo AI:", error);
        return null;
    }
};

const dialogueResponseSchema = {
    type: Type.OBJECT,
    properties: {
        nextLine: {
            type: Type.STRING,
            description: "Risposta dell'incubo. Stile 'Amnesia Concreta': breve, sensoriale, confusa. Massimo 25 parole."
        },
        empathyScore: {
            type: Type.INTEGER,
            description: "Punteggio 1-10. 1-3: Banale/Aggressivo. 4-6: Vago/Filosofico (Penalizzato!). 7-10: Investigativo/Specifico (cita dettagli sensoriali o soddisfa il Bisogno Nascosto)."
        },
        reasoning: {
            type: Type.STRING,
            description: "Una breve spiegazione (massimo 15 parole) del motivo per cui hai assegnato questo punteggio. Spiega cosa il giocatore ha fatto bene o male (es. 'Ha capito il bisogno', 'Troppo astratto')."
        }
    },
    required: ['nextLine', 'empathyScore', 'reasoning']
};

export const getDialogueResponse = async (enemy: Enemy, history: {speaker: string, text: string}[], profile: any): Promise<{ nextLine: string; empathyScore: number; reasoning: string } | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

        const formattedHistory = history.map(turn => `${turn.speaker === 'player' ? 'Giocatore' : enemy.name}: ${turn.text}`).join('\n');
        const hpPercentage = Math.round((enemy.hp / enemy.maxHp) * 100);
        const difficultyState = hpPercentage > 50 ? "ARROGANTE e FORTE (Difficile da convincere)" : "FERITO e VULNERABILE (Cerca aiuto)";

        const prompt = `
            Sei l'incubo "${enemy.name}". Non sei un mostro, sei: ${profile.humanIdentity} che ha subito: ${profile.tragicEvent}.
            Stato Attuale: ${difficultyState}.
            Dettagli Sensoriali Chiave: ${profile.sensoryDetails.join(", ")}.
            IL TUO BISOGNO PROFONDO: ${profile.hiddenNeed}.

            Stile Dialogo: "Amnesia Concreta". 
            Parla per immagini sensoriali.
            Usa frasi spezzate ma evocative.
            Massimo 25 parole.
            Mescola i dettagli sensoriali fisici con le emozioni.

            Conversazione:
            ${formattedHistory}

            Ultima frase Giocatore: "${history[history.length - 1].text}"

            VALUTAZIONE (Sii un Giudice Severo):
            - Punteggio 1-3 (Fallimento): Il giocatore usa frasi fatte ("calmati", "smetti"), è aggressivo, o ignora i tuoi lamenti fisici.
            - Punteggio 4-6 (Neutrale/Negativo): Il giocatore usa concetti astratti o filosofici ("trova la pace", "la luce è in te"). Tu odi l'astrazione, vuoi concretezza.
            - Punteggio 7-10 (Successo): Il giocatore agisce come un DETECTIVE o TERAPEUTA. Ha intuito la tua identità umana, ha citato un Dettaglio Sensoriale Chiave o ha soddisfatto il tuo BISOGNO PROFONDO.

            Genera risposta, voto e spiegazione (reasoning) in JSON.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: dialogueResponseSchema,
            },
        });

        const jsonString = response.text;
        return JSON.parse(jsonString);

    } catch (error) {
        console.error("Errore durante la generazione della risposta del dialogo:", error);
        return null;
    }
};


