                        ) : (
                            <p>Caricamento dati missione...</p>
                        )}
                    </div>
                </>
            );
        }
        if (isExpanded === 'magic') {
            const spellSlots = [...player.spells];
            const emptySpellSlotsCount = MAX_SPELLS - spellSlots.length;

            return (
                <>
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    <div className="magic-inventory-panel" onMouseLeave={() => setHoveredItem(null)}>
                        <h4>Intenzioni</h4>
                        <div className={`inventory-grid inventory-grid-${MAX_SPELLS}`}>
                            {spellSlots.map((spell) => {
                                const displayInfo = getDisplayInfoForItem(spell);
                                const canCast = player.coins >= spell.costToUse;
                                const isCastDisabled = !canCast || player.hasCastSpellThisTurn;

                                const getTitle = () => {
                                    if (player.hasCastSpellThisTurn) return "Hai già lanciato un'intenzione in questo turno.";
                                    if (!canCast) return `Intento insufficiente (${player.coins}/${spell.costToUse})`;
                                    return spell.name;
                                };

                                const contextMenuOptions = [{
                                    label: 'Lancia Intenzione',
                                    action: () => onCastSpell(player.id, spell.id),
                                    disabled: isCastDisabled
                                }];

                                return (
                                    <div key={spell.id} className="inventory-slot-wrapper clickable"
                                        onContextMenu={(e) => openContextMenu(e, contextMenuOptions)}
                                        onMouseEnter={() => setHoveredItem(spell)}
                                        title={getTitle()}
                                    >
                                        <div className="slot-level-indicator-container" />
                                        <div className={`inventory-slot magic-slot ${isCastDisabled ? 'disabled' : ''}`}>
                                            <img src={displayInfo.image} alt={displayInfo.name} />
                                        </div>
                                    </div>
                                );
                            })}
                            {Array.from({ length: emptySpellSlotsCount }).map((_, index) => (
                                <div key={`empty-spell-slot-${index}`} className="inventory-slot-wrapper">
                                    <div className="slot-level-indicator-container" />
                                    <div className="inventory-slot empty" />
                                </div>
                            ))}
                        </div>
                         <div className="weapon-preview-panel">
                            {hoveredItem && hoveredItem.type === 'intention' ? (() => {
                                const spell = hoveredItem as MagicSpell;
                                return (
                                    <>
                                        <h4>{spell.name}</h4>
                                        <strong>Costo: {spell.costToUse} Intento</strong>
                                        <p className="weapon-effect-description">{spell.description}</p>
                                    </>
                                )
                            })() : (
                                <p className="preview-placeholder">Passa il mouse su un'intenzione per i dettagli.</p>
                            )}
                        </div>
                    </div>
                </>
            );
        }
        if (isExpanded === 'inventory') {
            const inventoryItems = [...player.inventory];
            const emptySlotsCount = player.inventorySize - inventoryItems.length;

            return (
                <>
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    {renderEquippedWeaponDisplay()}
                    <div className="dice-pools-container">
                        <DicePoolDisplay dice={player.attackDice} title="Arm." playerColor={playerColorHex[player.color]} />
                        <DicePoolDisplay dice={player.defenseDice} title="Stab." playerColor={playerColorHex[player.color]} />
                    </div>
                    <div className={`inventory-grid inventory-grid-${player.inventorySize}`} onMouseLeave={() => setHoveredItem(null)}>
                        {inventoryItems.map((item, index) => {
                            const isWeapon = item.type === 'melee' || item.type === 'ranged' || item.type === 'magic';
                            const isConsumable = item.type === 'potion' || item.type === 'spellScroll' || item.type === 'bag';

                            const contextMenuOptions = [];
                            if (!player.isDead) {
                                if (isWeapon) {
                                    contextMenuOptions.push({ label: 'Equipaggia', action: () => onEquipWeapon(player.id, index) });
                                }
                                if (isConsumable) {
                                    contextMenuOptions.push({ label: 'Usa', action: () => onUseConsumable(player.id, index) });
                                }
                                contextMenuOptions.push({ label: 'Lascia', action: () => onDropWeapon(player.id, index) });
                            }
                             const displayInfo = getDisplayInfoForItem(item);
                            return (
                                <div key={item.id || `item-${index}`} className={`inventory-slot-wrapper clickable`}
                                    onContextMenu={(e) => {
                                        if (contextMenuOptions.length > 0) {
                                            openContextMenu(e, contextMenuOptions);
                                        }
                                    }}
                                    onMouseEnter={() => setHoveredItem(item)}>
                                    <div className="slot-level-indicator-container">
                                        {displayInfo.level !== null && (<span className="slot-level-indicator">Liv: {displayInfo.level}</span>)}
                                    </div>
                                    <div className="inventory-slot">
                                        <img src={displayInfo.image} alt={displayInfo.name} title={displayInfo.name} />
                                    </div>
                                </div>
                            );
                        })}
                        {Array.from({ length: emptySlotsCount }).map((_, index) => (
                            <div key={`empty-slot-${index}`} className="inventory-slot-wrapper">
                                <div className="slot-level-indicator-container" />
                                <div className="inventory-slot empty" />
                            </div>
                        ))}
                    </div>
                    <div className="weapon-preview-panel">
                        {hoveredItem ? (() => {
                             const info = getDisplayInfoForItem(hoveredItem);
                            if (hoveredItem.type === 'intention') {
                                const spell = hoveredItem as MagicSpell;
                                 return <><h4>{info.name}</h4><strong>Costo Acquisto: {spell.costToBuy} Intento</strong><p className="weapon-effect-description">{info.description}</p></>;
                            }
                            const isWeapon = hoveredItem.type === 'melee' || hoveredItem.type === 'ranged' || hoveredItem.type === 'magic';
                            return (
                                <>
                                    <h4>{info.name} {info.level !== null ? `(Liv: ${info.level})` : ''}</h4>
                                    {isWeapon && <strong>"{(hoveredItem as Weapon).bonusEffect.name}"</strong>}
                                    <p className="weapon-effect-description">{info.description}</p>
                                </>
                            )
                        })() : (
                            <p className="preview-placeholder">Passa il mouse su un oggetto per i dettagli.</p>
                        )}
                    </div>
                </>
            );
        }
        return null;
    };

    return (
        <div className="player-stat-card" style={{ borderColor: playerColorHex[player.color] }} onClick={() => onClick(player.id)}>
            {player.hasNewItem && <div className="new-item-indicator" title="Nuovo oggetto nell'inventario!">🎒</div>}
            {renderContent()}
        </div>
    );
};


const App = () => {
  // Dimensioni per le miniature (player, nemici, etc.)
  const PAWN_WIDTH = 40;
  const PAWN_HEIGHT = 40;
  // Dimensioni per le icone (tesori, armi, etc.)
  const ICON_WIDTH = 20;
  const ICON_HEIGHT = 20;
  const PAWN_ANIMATION_SPEED = 200; // ms per casella
  const AI_THINK_DELAY = 1500; // ms

  const [view, setView] = useState<'splash' | 'selection' | 'loading' | 'game'>('splash');
  const [gameState, setGameState] = useState<GameState>(initialGameState);
  const [gameSettings, setGameSettings] = useState<GameSettings | null>(null);
  const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
  const [ghostPawnPosition, setGhostPawnPosition] = useState<number | null>(null);
  const [modalInfo, setModalInfo] = useState<ModalInfo | null>(null);
  const [isModalClosing, setIsModalClosing] = useState(false);
  const [expansionState, setExpansionState] = useState<Record<number, 'equipped' | 'inventory' | 'quest' | 'magic'>>({});
  const [contextMenuInfo, setContextMenuInfo] = useState<ContextMenuProps | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isUpgradeModalOpen, setIsUpgradeModalOpen] = useState(false);
  const [toastInfo, setToastInfo] = useState<{ message: string; id: number } | null>(null);
  const previousKeysRef = useRef<GameState['keys']>(gameState.keys); // for key notifications
  const previousTrustLevelRef = useRef<string>(gameState.trustLevel); // for trust notifications

  // --- STATO PER ANIMAZIONE ---
  const [isAnimating, setIsAnimating] = useState(false); // Usato per animazioni di movimento e turni IA
  const [pawnVisualPositions, setPawnVisualPositions] = useState<PawnVisualPositions>({});
  const [isGameReady, setIsGameReady] = useState(false);


  // --- Board Dimensions & Cells ---
  const { allCells, viewBoxWidth, viewBoxHeight, PADDING, getCellCoordinatesById } = gameEngine.boardLayout;

  const playerColorHex: Record<string, string> = {
    red: '#c0392b',
    yellow: '#f1c40f',
    white: '#aeb6bf',
    black: '#2c3e50',
  };


  // --- App Flow ---
  const handleSplashClick = () => {
    document.documentElement.requestFullscreen().catch(err => {
        console.warn(`Errore nell'attivare la modalità schermo intero: ${err.message} (${err.name})`);
    });
    // Initialize AudioContext on first user interaction
    AudioManager.initialize();
    setView('selection');
  };

  const handleSettingsConfirm = (settings: GameSettings) => {
    AudioManager.setAudioEnabled(settings.audio);
    setGameSettings(settings);
    setIsCustomizeModalOpen(true);
  };

  const handleGameStart = async (customizations: PlayerCustomization[]) => {
      if (!gameSettings) return;
      setIsCustomizeModalOpen(false);
      setView('loading');

      try {
        const newGameState = await createInitialGameState(gameSettings.players, customizations, gameSettings.mode);
        setGameState(newGameState);
        setView('game');
      } catch (error) {
          console.error("Failed to initialize game:", error);
          alert("Could not start the game. The AI service may be unavailable. Please try again or play in offline mode.");
          setView('selection');
      }
  };

    const pawnPositionsSignature = useMemo(() => {
        const allPawns = [...gameState.players, ...gameState.enemies, ...gameState.merchants, ...gameState.npcs];
        allPawns.sort((a, b) => a.id - b.id); // Assicura un ordine stabile per la stringa
        return JSON.stringify(allPawns.map(p => ({ id: p.id, pos: p.position })));
    }, [gameState]);


    // Helper function to generate a unique key for any pawn-like entity.
    const getPawnKey = (pawn: any): string => {
        if ('color' in pawn) return `player_${pawn.id}`; // Player
        if ('stock' in pawn) return `merchant_${pawn.id}`; // Merchant
        if ('quest' in pawn) return `npc_${pawn.id}`; // NPC
        if ('hp' in pawn && !('color' in pawn)) return `enemy_${pawn.id}`; // Enemy
        return `unknown_${pawn.id}`; // Fallback
    };

  // --- Inizializzazione e Sincronizzazione delle Posizioni Visive ---
    useEffect(() => {
        const newVisuals: PawnVisualPositions = {};

        // 1. Raggruppa tutte le miniature visibili per cella
        const pawnsByCell = new Map<number, any[]>();
        const allVisiblePawns = [
            ...gameState.players,
            ...gameState.enemies.filter(e => e.isVisible),
            ...gameState.merchants.filter(m => m.isVisible),
            ...gameState.npcs.filter(n => n.isVisible),
        ];

        allVisiblePawns.forEach(pawn => {
            const pos = pawn.position;
            if (!pawnsByCell.has(pos)) pawnsByCell.set(pos, []);
            pawnsByCell.get(pos)!.push(pawn);
        });

        // Helper to get corner positions based on the number of pawns
        const getCornerPositions = (cellCoords: { x: number, y: number, width: number, height: number }, count: number, pawnWidth: number, pawnHeight: number) => {
            const positions: { x: number, y: number }[] = [];
            const { x, y, width, height } = cellCoords;
            const topLeft = { x: x, y: y };
            const topRight = { x: x + width - pawnWidth, y: y };
            const bottomLeft = { x: x, y: y + height - pawnHeight };
            const bottomRight = { x: x + width - pawnWidth, y: y + height - pawnHeight };

            switch (count) {
                case 2:
                    positions.push(topLeft, bottomRight); // Diagonale
                    break;
                case 3:
                    positions.push(topLeft, topRight, bottomLeft); // a L
                    break;
                case 4:
                default: // Gestisce 4 o più pedine
                    positions.push(topLeft, topRight, bottomLeft, bottomRight);
                    break;
            }
            return positions;
        };

        // 2. Itera su ogni cella e calcola il layout
        pawnsByCell.forEach((pawnsOnCell, cellId) => {
            const coords = getCellCoordinatesById(cellId);
            if (!coords) return;

            if (pawnsOnCell.length > 1) {
                // Più di una miniatura: ridimensiona e posiziona negli angoli
                const newWidth = PAWN_WIDTH / 2;
                const newHeight = PAWN_HEIGHT / 2;
                const cornerPositions = getCornerPositions(coords, pawnsOnCell.length, newWidth, newHeight);

                pawnsOnCell.forEach((pawn, index) => {
                    const key = getPawnKey(pawn);
                    const pos = cornerPositions[index % 4]; // Usa modulo per gestire più di 4 pedine
                    newVisuals[key] = {
                        x: pos.x,
                        y: pos.y,
                        width: newWidth,
                        height: newHeight,
                    };
                });
            } else {
                // Una sola miniatura: posiziona al centro a dimensione intera
                const pawn = pawnsOnCell[0];
                const key = getPawnKey(pawn);
                newVisuals[key] = {
                    x: coords.x + (coords.width - PAWN_WIDTH) / 2,
                    y: coords.y + (coords.height - PAWN_HEIGHT) / 2 - 10,
                    width: PAWN_WIDTH,
                    height: PAWN_HEIGHT,
                };
            }
        });

        setPawnVisualPositions(newVisuals);

    }, [pawnPositionsSignature, getCellCoordinatesById]);


  // --- Helper Functions ---
  const getEntityKey = (entity: any) => `${entity.name}_${entity.id}`;

  const getEntityType = (entity: any): 'pawn' | 'icon' => {
      // Players, Enemies, Merchants, NPCs are 'pawns' (miniatures)
      if ('color' in entity || 'hp' in entity || 'quest' in entity || (entity.name && entity.name.startsWith('Genio'))) {
          return 'pawn';
      }
      // Treasures, WorldItems, SpecialSquares are 'icons'
      return 'icon';
  };

  const allEntitiesToRender = gameEngine.getVisibleEntities(gameState);
  const pawnsToRender = allEntitiesToRender.filter(e => getEntityType(e) === 'pawn');
  const iconsToRender = allEntitiesToRender.filter(e => getEntityType(e) === 'icon');

  // Ordina le pedine in base alla coordinata Y per garantire un corretto ordine di sovrapposizione
  const sortedPawnsToRender = useMemo(() => {
      return [...pawnsToRender].sort((a, b) => {
          const keyA = getPawnKey(a);
          const keyB = getPawnKey(b);
          const visualA = pawnVisualPositions[keyA];
          const visualB = pawnVisualPositions[keyB];

          if (!visualA || !visualB) {
              return 0; // Non ordinare se le informazioni visive non sono pronte
          }

          // Ordinamento primario per coordinata y
          if (visualA.y !== visualB.y) {
              return visualA.y - visualB.y;
          }

          // Ordinamento secondario per pedine allo stesso livello y (opzionale ma stabile)
          return visualA.x - visualB.x;
      });
  }, [pawnsToRender, pawnVisualPositions]);


  // --- Game Actions ---
  const handleRollDice = async () => {
    const currentPlayer = gameState.players[gameState.currentPlayerIndex];
    if (currentPlayer.isDead || isAnimating || currentPlayer.controller === 'ai') return;

    setGameState(gs => {
        const { newState, roll } = gameEngine.rollDice(gs);
        showDiceRoll([roll], `Lancio per ${currentPlayer.name}...`, playerColorHex[currentPlayer.color]);
        return newState;
    });
  };

  const handleEndTurn = () => {
    if (isAnimating) return;
    setGameState(gs => {
        const { newState, modalInfo: turnModal, audioAnnouncement } = gameEngine.endTurn(gs);
        if (turnModal) {
            setModalInfo(turnModal);
        }
        if (audioAnnouncement) {
            AudioManager.playAnnouncement(audioAnnouncement);
        }
        return newState;
    });
    setExpansionState({});
  };

  const animatePawnAlongPath = (path: number[], finalTargetId: number) => {
    let currentStep = 0;
    const playerKey = getPawnKey(gameState.players[gameState.currentPlayerIndex]);

    const moveNext = () => {
      if (currentStep >= path.length) {
        // Animation finished, now resolve the landing
        setGameState(gs => {
