            }
            return newState;
        });
        setIsAnimating(false);
        return;
      }

      const nextCellId = path[currentStep];
      const coords = getCellCoordinatesById(nextCellId);
      if (coords) {
        setPawnVisualPositions(prev => ({
          ...prev,
          [playerKey]: {
            ...prev[playerKey],
            x: coords.x + (coords.width - PAWN_WIDTH) / 2,
            y: coords.y + (coords.height - PAWN_HEIGHT) / 2 - 10,
          }
        }));
