interface HPSacrificeModalContentProps {
    maxHP: number;
    onSacrifice: (amount: number) => void;
}

export const HPSacrificeModalContent: React.FC<HPSacrificeModalContentProps> = ({ maxHP, onSacrifice }) => {
    // Sacrifice from 1 to 5, but cannot kill player (must stay with at least 1 HP)
    const options = [1, 2, 3, 4, 5].filter(opt => opt < maxHP);

    return (
        <div style={{ textAlign: 'center' }}>
            <p>Quanta Volontà desideri trasformare in Intento?</p>
            <p><small>(Ogni punto Volontà fornisce 4 Intento)</small></p>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', marginTop: '20px' }}>
                {options.map(opt => (
                    <button 
                        key={opt} 
                        className="modal-action-button confirm" 
                        onClick={() => onSacrifice(opt)}
                    >
                        {opt} ❤️
                    </button>
                ))}
            </div>
            {options.length === 0 && <p style={{color: '#c0392b', fontWeight: 'bold'}}>La tua Volontà è troppo bassa per questo sacrificio.</p>}
        </div>
    );
};

interface RevealTypeModalContentProps {
    onSelect: (type: KeyColor) => void;
}

export const RevealTypeModalContent: React.FC<RevealTypeModalContentProps> = ({ onSelect }) => {
    const types: KeyColor[] = ['black', 'white', 'yellow', 'red'];

    return (
        <div style={{ textAlign: 'center' }}>
            <p>Scegli quale categoria di incubi desideri individuare:</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '15px', marginTop: '20px' }}>
                {types.map(type => (
                    <button 
                        key={type} 
                        className="modal-action-button" 
                        onClick={() => onSelect(type)}
                        style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '5px' }}
                    >
                        <img src={preloadedAssets.enemies[type][0]} alt={type} style={{ width: '30px', height: '40px' }} />
                        <span>{ENEMY_TYPE_NAMES[type].plural}</span>
                    </button>
                ))}
            </div>
        </div>
    );
};

interface CopySpellModalContentProps {
    modalInfo: Extract<ModalInfo, { type: 'copy_spell_prompt' }>;
}

export const CopySpellModalContent: React.FC<CopySpellModalContentProps> = ({ modalInfo }) => {
    const { spell } = modalInfo;
