export const generateEnemyNamesFromAI = async (): Promise<Record<KeyColor, string[]> | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const prompt = `
            Sei il Game Master di un gioco da tavolo onirico e poetico chiamato 'Competo'.
            Devi creare i nomi per 10 incubi che i giocatori affronteranno.
            Gli incubi sono divisi in 4 tipi con temi specifici:
            - Oscuri (tema: morte, lutto): es. Decadimento, Disgregamento.
            - Luminosi (tema: perfezionismo, corruzione): es. Depravazione, Sozzura.
            - Acidi (tema: immobilità, stasi): es. Stallo, Inerzia.
            - Ardenti (tema: rabbia, delirio): es. Delirio, Impeto.

            Genera nomi unici e creativi. Sii poetico e malinconico.
            JSON output.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: enemyNamesSchema,
            },
        });

        return JSON.parse(response.text) as Record<KeyColor, string[]>;

    } catch (error) {
        console.error("Errore generazione nomi:", error);
        return null;
    }
};


export const generateQuestForNPC = async (gameState: GameState): Promise<Quest | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const currentPlayer = gameState.players[gameState.currentPlayerIndex];
        const existingQuests = gameState.players.map(p => p.activeQuestId).filter(Boolean);

        const prompt = `
            Sei il Game Master di 'Competo'. 
            Un giocatore di nome ${currentPlayer.name} (livello ${currentPlayer.level}) ha incontrato un 'Disperso'.
            Crea una missione poetica e malinconica.
            Evita queste missioni: ${existingQuests.join(', ')}.
            JSON output.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: questSchema,
            },
        });

        const generatedQuest = JSON.parse(response.text) as Omit<Quest, 'id'>;
        return { id: `gen_${Date.now()}`, ...generatedQuest };

    } catch (error) {
        console.error("Errore generazione missione:", error);
        return null;
    }
};

