export const prepareDialogueAI = async (enemy: Enemy): Promise<any | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const archetypeInfo = ENEMY_ARCHETYPES[enemy.enemyType];

        const prompt = `
            Genera un profilo psicologico per l'incubo "${enemy.name}".
            Archetipo: ${archetypeInfo}
            Definisci chi era come umano e quale loop di dolore lo tiene sveglio nel sogno.
            JSON output.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: dialogueProfileSchema,
            },
        });

        return JSON.parse(response.text);
    } catch (error) {
        return null;
    }
};

const dialogueResponseSchema = {
    type: Type.OBJECT,
    properties: {
        nextLine: { type: Type.STRING },
        empathyScore: { type: Type.INTEGER },
        isDreamerEmerging: { type: Type.BOOLEAN },
        reasoning: { type: Type.STRING }
    },
    required: ['nextLine', 'empathyScore', 'isDreamerEmerging', 'reasoning']
};

export const getDialogueResponse = async (enemy: Enemy, history: {speaker: string, text: string}[], profile: any, currentRapport: number): Promise<{ nextLine: string; empathyScore: number; reasoning: string } | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
        const formattedHistory = history.map(turn => `${turn.speaker}: ${turn.text}`).join('\n');

        const prompt = `
            Sei l'entità "${enemy.name}" (Sognatore bloccato: ${profile.humanIdentity}).
            Trauma Loop: ${profile.traumaLoop}.
            Rapporto attuale: ${currentRapport}.
            Rispondi al giocatore (Guida Lucida). Se il rapporto è basso sii delirante. Se è alto inizia a ricordare.
            Storia: ${formattedHistory}
            JSON output.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: dialogueResponseSchema,
            },
        });

        return JSON.parse(response.text);
    } catch (error) {
        return null;
    }
};

const recomposedResponseSchema = {
    type: Type.OBJECT,
    properties: { nextLine: { type: Type.STRING } },
    required: ['nextLine']
};

export const getRecomposedDialogueResponse = async (enemy: Enemy, history: {speaker: string, text: string}[], profile: any): Promise<{ nextLine: string } | null> => {
     try {
