// --- Map Health Bar ---
const MapHealthBar: React.FC<{enemy: Enemy}> = ({ enemy }) => {
    const coords = gameEngine.boardLayout.getCellCoordinatesById(enemy.position);
    if (!coords) return null;

    const barWidth = 25;
    const barHeight = 5;
    const barX = coords.x + (coords.width - barWidth) / 2;
    const barY = coords.y + coords.height - barHeight - 1;
    const percentage = (enemy.hp / enemy.maxHp) * 100;

    return (
        <g key={`hp-${enemy.id}`} className="map-hp-bar">
            <rect x={barX} y={barY} width={barWidth} height={barHeight} fill="#e9ecef" stroke="black" strokeWidth="0.5" rx="1"/>
            <rect x={barX} y={barY} width={(barWidth * percentage) / 100} height={barHeight} fill="#c0392b" rx="1"/>
        </g>
    );
};


// --- Health Bar Component ---
const HealthBar: React.FC<{currentHp: number, maxHp: number, isEnemy?: boolean}> = ({ currentHp, maxHp, isEnemy = false }) => {
    const percentage = maxHp > 0 ? (currentHp / maxHp) * 100 : 0;
    const title = isEnemy ? `Paura: ${currentHp} / ${maxHp}` : `Volontà: ${currentHp} / ${maxHp}`;
    return (
        <div className="hp-bar-container" title={title}>
            <div className="hp-bar" style={{ width: `${percentage}%` }}></div>
            <span className="hp-bar-text">{currentHp} / {maxHp}</span>
        </div>
    );
};

// --- Intent Bar Component ---
const IntentBar: React.FC<{currentIntent: number}> = ({ currentIntent }) => {
    const displayMax = currentIntent > 20 ? currentIntent : 20;
    const percentage = displayMax > 0 ? (currentIntent / displayMax) * 100 : 0;
    const title = `Intento: ${currentIntent}`;
    const text = currentIntent > 20 ? currentIntent : `${currentIntent} / 20`;
    return (
        <div className="intent-bar-container" title={title}>
            <div className="intent-bar" style={{ width: `${percentage}%` }}></div>
            <span className="intent-bar-text">{text}</span>
        </div>
    );
};

// --- Status Effects Display ---
const StatusEffects: React.FC<{ player: Player }> = ({ player }) => {
    const effects: { key: string, text: string, title: string, type: 'positive' | 'negative' }[] = [];

    if (player.nextCombatAttackDiceModifier && player.nextCombatAttackDiceModifier > 0) {
        effects.push({ key: 'coraggio', text: `⚔️+${player.nextCombatAttackDiceModifier} Coraggio`, title: `Lanci ${player.nextCombatAttackDiceModifier} dado/i attacco in più nel prossimo combattimento.`, type: 'positive' });
    }
    if (player.nextCombatAttackDiceModifier && player.nextCombatAttackDiceModifier < 0) {
        effects.push({ key: 'paura', text: `⚔️${player.nextCombatAttackDiceModifier} Paura`, title: `Lanci ${Math.abs(player.nextCombatAttackDiceModifier)} dado/i attacco in meno nel prossimo combattimento.`, type: 'negative' });
    }
    if (player.skipNextTurn) {
        effects.push({ key: 'pigrizia', text: `⏭️ Pigrizia`, title: `Salterai il tuo prossimo turno.`, type: 'negative' });
    }
    if (player.nextRollHalved) {
        effects.push({ key: 'affaticamento', text: `🎲½ Affaticamento`, title: `Il risultato del tuo prossimo lancio di dado sarà dimezzato.`, type: 'negative' });
    }
    if (player.negateNextDamage) {
        effects.push({ key: 'sostegno', text: `🛡️ Sostegno`, title: `Annullerai il prossimo danno che dovresti subire in combattimento.`, type: 'positive' });
    }
    if (player.nextPurchaseDiscount) {
        effects.push({ key: 'efficienza', text: `💰 Efficienza`, title: `Il prossimo acquisto da un Genio costerà il ${player.nextPurchaseDiscount * 100}% in meno.`, type: 'positive' });
    }

    if (effects.length === 0) return null;

    return (
        <div className="status-effects-container">
            {effects.map(effect => (
                <span key={effect.key} className={`status-effect ${effect.type}`} title={effect.title}>
                    {effect.text}
                </span>
            ))}
        </div>
    );
};


// --- Player Card Component ---
interface PlayerCardProps {
    player: Player;
    isExpanded: 'equipped' | 'inventory' | 'quest' | 'magic' | false;
    onClick: (playerId: number) => void;
    onQuestIconClick: (e: React.MouseEvent, playerId: number) => void;
    onMagicIconClick: (e: React.MouseEvent, playerId: number) => void;
    openContextMenu: (e: React.MouseEvent, options: any[]) => void;
    onEquipWeapon: (playerId: number, inventoryIndex: number) => void;
    onUnequipWeapon: (playerId: number) => void;
    onDropWeapon: (playerId: number, inventoryIndex: number) => void;
    onDropEquippedWeapon: (playerId: number) => void;
    onUseConsumable: (playerId: number, inventoryIndex: number) => void;
    onCastSpell: (playerId: number, spellId: string) => void;
    gameState: GameState;
}

const PlayerCard: React.FC<PlayerCardProps> = ({
    player, isExpanded, onClick, onQuestIconClick, onMagicIconClick, openContextMenu,
    onEquipWeapon, onUnequipWeapon, onDropWeapon, onDropEquippedWeapon, onUseConsumable, onCastSpell, gameState
}) => {
    const playerColorHex: Record<string, string> = { red: '#c0392b', yellow: '#f1c40f', white: '#aeb6bf', black: '#2c3e50' };
    const [hoveredItem, setHoveredItem] = useState<InventoryItem | null>(null);

    const getDisplayInfoForItem = (item: InventoryItem | null) => {
        if (!item) return { image: preloadedAssets.items.emptySlot, level: null, name: 'Slot vuoto', description: '' };

        switch (item.type) {
            case 'melee':
            case 'ranged':
            case 'magic':
                const weapon = item as Weapon;
                return { image: preloadedAssets.items.weapons[weapon.name] || preloadedAssets.items.weapons.generic, level: weapon.level, name: weapon.name, description: weapon.bonusEffect.description };
            case 'potion':
            case 'spellScroll':
            case 'bag':
                const consumable = item as Consumable;
                return { image: preloadedAssets.items.consumables[consumable.name] || preloadedAssets.items.weapons.generic, level: null, name: consumable.name, description: consumable.description };
            case 'questItem':
                const questItem = item as { name: string; type: 'questItem' };
                return { image: preloadedAssets.items.questItems[questItem.name] || preloadedAssets.items.treasure, level: null, name: questItem.name, description: 'Oggetto necessario per una missione.' };
            case 'intention':
                const spell = item as MagicSpell;
                return { image: preloadedAssets.magicSpells[spell.name] || preloadedAssets.items.weapons.generic, level: null, name: spell.name, description: spell.description };
            default:
                return { image: preloadedAssets.items.emptySlot, level: null, name: 'Slot vuoto', description: '' };
        }
    }


    const DieIcon: React.FC<{ color: string, className?: string }> = ({ color, className }) => {
        const dotColor = (color === '#2c3e50' || color === '#c0392b') ? '#ffffff' : '#000000';
        return (
            <svg viewBox="0 0 24 24" width="1em" height="1em" className={className} style={{ verticalAlign: 'middle' }}>
              <rect x="3" y="3" width="18" height="18" rx="3" fill={color} stroke="rgba(0,0,0,0.4)" strokeWidth="1.5" />
              <circle cx="12" cy="12" r="2.5" fill={dotColor} />
            </svg>
        );
    };

    const DicePoolDisplay: React.FC<{ dice: DieConfig[], title: string, playerColor?: string }> = ({ dice, title, playerColor }) => {
        if (!dice || dice.length === 0) return null;
        return (
            <div className="dice-pool-display">
                <span className="dice-pool-title">{title}:</span>
                <div className="dice-pool-icons">
                    {dice.map((die) => (
                        <div key={die.id} className="dice-pool-icon" title={`Dado ${die.id + 1}, Risonanze: ${die.hits}, Profonde: ${die.hasCrit ? 1 : 0}`}>
                            <DieIcon color={playerColor || '#333'} />
                            {die.hasCrit && <span className="dice-crit-indicator">✨</span>}
                            {die.bonusHits > 0 && <span className="dice-upgrade-badge">{die.bonusHits}</span>}
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    const renderPlayerCardHeader = () => (
        <div className="player-card-top-row">
            <div className="player-avatar-container">
                <img src={player.avatar} alt={`${player.name} avatar`} className="player-avatar"/>
            </div>
            <div className="player-main-info">
                <h3>{player.name} {player.isDead ? '(Sconfitto)' : ''}</h3>
                <div className="player-stats-inline">
                    <span title="Determinazione">Liv: {player.level}</span>
                    <span title="Stabilità: determina il numero di dadi stabilizzazione">🛡️: {player.toughness}</span>
                    <span title={`Incubi ${player.color} ricomposti: ${player.keyQuestProgress}/5`}>💀: {player.keyQuestProgress}/5</span>
                </div>
                 <StatusEffects player={player} />
            </div>
            {player.activeQuestId && (
                <button className="quest-indicator-button" onClick={(e) => onQuestIconClick(e, player.id)} title="Vedi Missione">!</button>
            )}
             <button className="magic-inventory-button" onClick={(e) => onMagicIconClick(e, player.id)} title="Vedi Intenzioni">
                <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                    <defs>
                        <linearGradient id="gold-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" style={{ stopColor: '#ffd700', stopOpacity: 1 }} />
                        <stop offset="100%" style={{ stopColor: '#f0bd17', stopOpacity: 1 }} />
                        </linearGradient>
                    </defs>
                    <path d="M12 11.5A2.5 2.5 0 0 1 9.5 9a2.5 2.5 0 0 1 2.5-2.5 2.5 2.5 0 0 0 0-5 7.5 7.5 0 0 0-7.5 7.5 7.5 7.5 0 0 0 7.5 7.5c4.14 0 7.5-3.36 7.5-7.5a7.5 7.5 0 0 0-7.5-7.5" fill="none" stroke="url(#gold-gradient)" strokeWidth="2" strokeLinecap="round"/>
                </svg>
            </button>
        </div>
    );

    const renderEquippedWeaponDisplay = () => {
        const weapon = player.equippedWeapon;
        const displayInfo = getDisplayInfoForItem(weapon);
        const isClickable = !!weapon;
        return (
            <div className="equipped-weapon-display">
                <div className={`inventory-slot-wrapper equipped-slot-wrapper ${isClickable ? 'clickable' : ''}`}
                    onContextMenu={(e) => {
                        if (isClickable) {
                            openContextMenu(e, [
                                { label: 'Riponi', action: () => onUnequipWeapon(player.id) },
                                { label: 'Lascia', action: () => onDropEquippedWeapon(player.id) },
                            ]);
                        }
                    }}>
                    <div className="slot-level-indicator-container">
                        {displayInfo.level !== null && (<span className="slot-level-indicator">Liv: {displayInfo.level}</span>)}
                    </div>
                    <div className={`inventory-slot equipped-slot ${!isClickable ? 'empty' : ''}`}>
                        <img src={displayInfo.image} alt={displayInfo.name} title={displayInfo.name} />
                    </div>
                    <span className="equipped-slot-label">Equip</span>
                </div>
                <div className="equipped-weapon-info">
                    {weapon ? (
                        <>
                            <h4>{weapon.name}</h4>
                            <p><strong>"{(weapon as Weapon).bonusEffect.name}"</strong></p>
                            {isExpanded === 'inventory' && <p className="weapon-effect-description">{weapon.bonusEffect.description}</p>}
                        </>
                    ) : (
                        <h4>Nessun desiderio equip.</h4>
                    )}
                </div>
            </div>
        );
    };

    const renderContent = () => {
        if (!isExpanded) { // Summary View
            return (
                <div className="player-card-summary-layout">
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    <div className="dice-pools-container">
                        <DicePoolDisplay dice={player.attackDice} title="Arm." playerColor={playerColorHex[player.color]} />
                        <DicePoolDisplay dice={player.defenseDice} title="Stab." playerColor={playerColorHex[player.color]} />
                    </div>
                </div>
            );
        }
        if (isExpanded === 'equipped') {
            return (
                <div className="player-card-summary-layout">
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    {renderEquippedWeaponDisplay()}
                    <div className="dice-pools-container">
                        <DicePoolDisplay dice={player.attackDice} title="Arm." playerColor={playerColorHex[player.color]} />
                        <DicePoolDisplay dice={player.defenseDice} title="Stab." playerColor={playerColorHex[player.color]} />
                    </div>
                </div>
            );
        }
        if (isExpanded === 'quest') {
            const activeQuestNpc = gameState.npcs.find(npc => npc.quest.id === player.activeQuestId);
            return (
                <>
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    <div className="quest-info-panel">
                        <h4>Missione Attiva</h4>
                        {activeQuestNpc ? (
                            <>
                                <p><strong>{activeQuestNpc.quest.title}</strong></p>
                                <p>{activeQuestNpc.quest.description}</p>
                                {player.activeQuestHint && <p className="quest-hint">{player.activeQuestHint}</p>}
                                <p className="quest-giver">- {activeQuestNpc.name}</p>
                            </>
                        ) : (
                            <p>Caricamento dati missione...</p>
                        )}
                    </div>
                </>
            );
        }
        if (isExpanded === 'magic') {
            const spellSlots = [...player.spells];
            // FIX: Ensure empty slots don't become negative during debug testing
            const emptySpellSlotsCount = Math.max(0, MAX_SPELLS - spellSlots.length);

            return (
                <>
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    <div className="magic-inventory-panel" onMouseLeave={() => setHoveredItem(null)}>
                        <h4>Intenzioni</h4>
                        <div className={`inventory-grid inventory-grid-${MAX_SPELLS}`}>
                            {spellSlots.map((spell) => {
                                const displayInfo = getDisplayInfoForItem(spell);
                                const canCast = player.coins >= spell.costToUse;
                                const isCastDisabled = !canCast || player.hasCastSpellThisTurn;

                                const getTitle = () => {
                                    if (player.hasCastSpellThisTurn) return "Hai già lanciato un'intenzione in questo turno.";
                                    if (!canCast) return `Intento insufficiente (${player.coins}/${spell.costToUse})`;
                                    return spell.name;
                                };

                                const contextMenuOptions = [{
                                    label: 'Lancia Intenzione',
                                    action: () => onCastSpell(player.id, spell.id),
                                    disabled: isCastDisabled
                                }];

                                return (
                                    <div key={spell.id} className="inventory-slot-wrapper clickable"
                                        onContextMenu={(e) => openContextMenu(e, contextMenuOptions)}
                                        onMouseEnter={() => setHoveredItem(spell)}
                                        title={getTitle()}
                                    >
                                        <div className="slot-level-indicator-container" />
                                        <div className={`inventory-slot magic-slot ${isCastDisabled ? 'disabled' : ''}`}>
                                            <img src={displayInfo.image} alt={displayInfo.name} />
                                        </div>
                                    </div>
                                );
                            })}
                            {Array.from({ length: emptySpellSlotsCount }).map((_, index) => (
                                <div key={`empty-spell-slot-${index}`} className="inventory-slot-wrapper">
                                    <div className="slot-level-indicator-container" />
                                    <div className="inventory-slot empty" />
                                </div>
                            ))}
                        </div>
                         <div className="weapon-preview-panel">
                            {hoveredItem && hoveredItem.type === 'intention' ? (() => {
                                const spell = hoveredItem as MagicSpell;
                                return (
                                    <>
                                        <h4>{spell.name}</h4>
                                        <strong>Costo: {spell.costToUse} Intento</strong>
                                        <p className="weapon-effect-description">{spell.description}</p>
                                    </>
                                )
                            })() : (
                                <p className="preview-placeholder">Passa il mouse su un'intenzione per i dettagli.</p>
                            )}
                        </div>
                    </div>
                </>
            );
        }
        if (isExpanded === 'inventory') {
            const inventoryItems = [...player.inventory];
            const emptySlotsCount = player.inventorySize - inventoryItems.length;

            return (
                <>
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    {renderEquippedWeaponDisplay()}
                    <div className="dice-pools-container">
                        <DicePoolDisplay dice={player.attackDice} title="Arm." playerColor={playerColorHex[player.color]} />
                        <DicePoolDisplay dice={player.defenseDice} title="Stab." playerColor={playerColorHex[player.color]} />
                    </div>
                    <div className={`inventory-grid inventory-grid-${player.inventorySize}`} onMouseLeave={() => setHoveredItem(null)}>
                        {inventoryItems.map((item, index) => {
                            const isWeapon = item.type === 'melee' || item.type === 'ranged' || item.type === 'magic';
                            const isConsumable = item.type === 'potion' || item.type === 'spellScroll' || item.type === 'bag';

                            const contextMenuOptions = [];
                            if (!player.isDead) {
                                if (isWeapon) {
                                    contextMenuOptions.push({ label: 'Equipaggia', action: () => onEquipWeapon(player.id, index) });
                                }
                                if (isConsumable) {
                                    contextMenuOptions.push({ label: 'Usa', action: () => onUseConsumable(player.id, index) });
                                }
                                contextMenuOptions.push({ label: 'Lascia', action: () => onDropWeapon(player.id, index) });
                            }
                             const displayInfo = getDisplayInfoForItem(item);
                            return (
                                <div key={item.id || `item-${index}`} className={`inventory-slot-wrapper clickable`}
                                    onContextMenu={(e) => {
                                        if (contextMenuOptions.length > 0) {
                                            openContextMenu(e, contextMenuOptions);
                                        }
                                    }}
