import { GameState, GamePhase, ModalInfo, Player, WeaponType, WorldItem, Enemy, CombatRollResultType, CombatPhase, CombatRollResult, Weapon, KeyColor, NPC, ItemReward, Consumable, Merchant, DieConfig, SpecialSquare, Treasure, InventoryItem, MagicSpell, TreasureType } from '../gameLogic';
import { blessingEffects, misfortuneEffects, GATE_CELLS, STOCK_REFRESH_TURN_INTERVAL, PLAYER_START_POSITIONS, baseWeapons, allConsumables, offlineQuests, ENEMY_TYPE_NAMES, ENEMY_NAMES_BY_TYPE, allMagicSpells, MAX_SPELLS } from './constants';
import { getRandomInt, createWeaponInstance, boardLayout as initialBoardLayout, generateMerchantStock } from './initialState';
import { preloadedAssets } from '../assets/preloadedAssets';

// --- TYPES ---
export type ItemArea = 'player_inventory' | 'player_equipped' | 'stash';
export interface ItemLocation {
    area: ItemArea;
    slot: number | string;
}

export type AIAction = { type: 'move'; targetCellId: number; } | { type: 'attack'; } | { type: 'use_consumable'; inventoryIndex: number; } | { type: 'end_turn'; };

// --- STATE MANAGEMENT ---
let currentGameState: GameState | null = null;
const updateCurrentGameState = (newState: GameState) => {
    currentGameState = newState;
    return newState;
}
export const getLatestState = (): GameState => {
    if (!currentGameState) throw new Error("Game state has not been initialized.");
    return JSON.parse(JSON.stringify(currentGameState));
}

// --- BOARD LAYOUT ---
export const boardLayout = {
    ...initialBoardLayout,
    getCellCoordinatesById: (id: number) => initialBoardLayout.allCells.find(c => c.id === id) || null
};

let _boardAdjacency: Record<number, number[]> | null = null;
const getBoardAdjacency = (): Record<number, number[]> => {
    if (_boardAdjacency) return _boardAdjacency;
    const adj: Record<number, number[]> = {};
    initialBoardLayout.allCells.forEach(c => { if (c.id) adj[c.id] = []; });
    for (let i = 1; i <= 48; i++) {
        adj[i].push(i === 48 ? 1 : i + 1, i === 1 ? 48 : i - 1);
    }
    adj[40].push(68); adj[68].push(40); adj[16].push(58); adj[58].push(16);
    adj[25].push(67); adj[67].push(25); adj[1].push(49); adj[49].push(1);
    [[68, 65], [65, 62], [62, 59], [59, 69], [58, 51], [51, 52], [52, 53], [53, 54], [54, 69], [67, 56], [56, 60], [60, 61], [61, 63], [63, 64], [64, 69], [49, 50], [50, 55], [55, 57], [57, 66], [66, 69]].forEach(([f, t]) => { adj[f].push(t); adj[t].push(f); });
    _boardAdjacency = adj;
    return adj;
};

export const findShortestPath = (startId: number, endId: number, gates: GameState['gates']): number[] | null => {
    if (startId === endId) return [startId];
    const adj = getBoardAdjacency();
    const queue: { cell: number, path: number[] }[] = [{ cell: startId, path: [startId] }];
    const visited = new Set([startId]);
    while (queue.length > 0) {
        const { cell, path } = queue.shift()!;
        if (cell === endId) return path;
        for (const next of adj[cell] || []) {
            if (visited.has(next)) continue;
            const isCrossingGate = (Object.values(GATE_CELLS).includes(cell) && !Object.values(GATE_CELLS).includes(next)) || (Object.values(GATE_CELLS).includes(next) && !Object.values(GATE_CELLS).includes(cell));
            if (isCrossingGate) {
                const gateCell = Object.values(GATE_CELLS).includes(cell) ? cell : next;
                const color = (Object.keys(GATE_CELLS) as KeyColor[]).find(k => GATE_CELLS[k] === gateCell);
                if (color && !gates[`${color}Open`]) continue;
            }
            visited.add(next);
            queue.push({ cell: next, path: [...path, next] });
        }
    }
    return null;
};

const calculateDistance = (s: number, e: number, g: GameState['gates']) => (findShortestPath(s, e, g)?.length || Infinity) - 1;

// --- ENGINE CORE ---
export const getVisibleEntities = (gs: GameState) => {
    currentGameState = gs;
    return [...gs.players, ...gs.enemies.filter(e => e.isVisible), ...gs.merchants.filter(m => m.isVisible), ...gs.treasures.filter(t => t.isVisible), ...gs.worldItems.filter(w => w.isVisible), ...gs.specialSquares.filter(s => s.isVisible), ...gs.npcs.filter(n => n.isVisible)];
};

export const rollDice = (gs: GameState): { newState: GameState, roll: number } => {
    let roll = getRandomInt(1, 6);
    const p = gs.players[gs.currentPlayerIndex];
    if (p.nextRollHalved) { roll = Math.max(1, Math.floor(roll / 2)); p.nextRollHalved = undefined; }
    const ns = { ...JSON.parse(JSON.stringify(gs)), diceResult: roll, gameStatePhase: 'moving' as GamePhase };
    ns.reachableCells = calculateReachableCells(ns);
    return { newState: updateCurrentGameState(ns), roll };
};

const calculateReachableCells = (gs: GameState): number[] => {
    const p = gs.players[gs.currentPlayerIndex];
    const roll = gs.diceResult;
    if (roll === 0) return [];
    const adj = getBoardAdjacency();
    const queue = [{ cell: p.position, dist: 0 }];
    const visited = new Map([[p.position, 0]]);
    const reachable = new Set<number>();
    while (queue.length > 0) {
        const { cell, dist } = queue.shift()!;
        if (dist > 0 && !gs.players.some(op => op.id !== p.id && op.position === cell && !op.isDead)) reachable.add(cell);
        if (dist >= roll) continue;
        for (const next of adj[cell] || []) {
            const isCrossingGate = (Object.values(GATE_CELLS).includes(cell) && !Object.values(GATE_CELLS).includes(next)) || (Object.values(GATE_CELLS).includes(next) && !Object.values(GATE_CELLS).includes(cell));
            if (isCrossingGate) {
                const color = (Object.keys(GATE_CELLS) as KeyColor[]).find(k => GATE_CELLS[k] === (Object.values(GATE_CELLS).includes(cell) ? cell : next));
                if (color && !gs.gates[`${color}Open`]) continue;
            }
            if (!visited.has(next) || visited.get(next)! > dist + 1) { visited.set(next, dist + 1); queue.push({ cell: next, dist: dist + 1 }); }
        }
    }
    return Array.from(reachable);
};

export const initiateCombat = (gs: GameState, enemyId: number, moved: boolean): { newState: GameState, modalInfo: ModalInfo | null } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const enemy = ns.enemies.find((e: Enemy) => e.id === enemyId);
    if (!enemy) return { newState: gs, modalInfo: null };
    enemy.isVisible = true; enemy.hasBeenAttacked = true;
    ns.gameStatePhase = 'combat';
    ns.combatState = { active: true, enemyId, hasPlayerMoved: moved, combatPhase: 'initial', playerRolls: null, enemyRolls: null, playerDefenseRolls: null, enemyDefenseRolls: null, attacksMadeThisTurn: 0, playerDamageTaken: null, enemyDamageTaken: null };
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};

export const endTurn = (gs: GameState): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const oldP = ns.players[ns.currentPlayerIndex];
    oldP.hasNewItem = oldP.hasCastSpellThisTurn = false;
    if (oldP.getsExtraTurn) { oldP.getsExtraTurn = false; ns.gameStatePhase = 'rolling'; return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Turno Extra!', message: 'Entusiasmo!' } }; }

    let nextIdx = (ns.currentPlayerIndex + 1) % ns.players.length;
    while (ns.players[nextIdx].isDead || ns.players[nextIdx].skipNextTurn) {
        if (ns.players[nextIdx].skipNextTurn) ns.players[nextIdx].skipNextTurn = false;
        nextIdx = (nextIdx + 1) % ns.players.length;
    }

    ns.currentPlayerIndex = nextIdx;
    ns.turnNumber += (nextIdx === 0 ? 1 : 0);
    ns.gameStatePhase = 'rolling';
    ns.diceResult = 0;
    ns.reachableCells = null;

    const newP = ns.players[nextIdx];
    if (newP.class === 'sentinella') {
        ns.enemies.forEach((e: Enemy) => { if (!e.isVisible && calculateDistance(newP.position, e.position, ns.gates) <= 2) e.isVisible = true; });
    }

    const enemyOnCell = ns.enemies.find((e: Enemy) => e.position === newP.position);
    if (enemyOnCell) {
        ns.gameStatePhase = 'end_turn';
        return { newState: updateCurrentGameState(ns), modalInfo: { type: 'enemy_encounter', title: 'Incubo!', enemy: enemyOnCell, dialogueRefused: Math.random() < 0.2, hasPlayerMoved: false } };
    }
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};

export const movePlayerAndResolveLanding = (gs: GameState, cellId: number): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string, levelUpInfo: any } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const oldPos = p.position;
    p.position = cellId; ns.gameStatePhase = 'end_turn'; ns.diceResult = 0; ns.reachableCells = null;

    const startPos = PLAYER_START_POSITIONS[p.id];
    if (oldPos < startPos && cellId >= startPos) {
        p.level++; p.maxHp += 5; p.hp = p.maxHp; p.toughness++;
        p.defenseDice.push({ id: p.defenseDice.length, hits: 2, bonusHits: 0, hasCrit: false });
    }

    const enemy = ns.enemies.find((e: Enemy) => e.position === cellId);
    if (enemy) return { newState: updateCurrentGameState(ns), modalInfo: { type: 'enemy_encounter', title: 'Incubo!', enemy, dialogueRefused: Math.random() < 0.2, hasPlayerMoved: true }, levelUpInfo: null };

    const merchant = ns.merchants.find((m: Merchant) => m.position === cellId);
    if (merchant) return { newState: updateCurrentGameState(ns), modalInfo: { type: 'merchant', title: 'Genio', merchant }, levelUpInfo: null };

    return { newState: updateCurrentGameState(ns), modalInfo: null, levelUpInfo: null };
};

// --- COMBAT LOGIC ---
const rollSingleDie = (die: DieConfig, isAtk: boolean): { res: CombatRollResultType, dmg: number } => {
    const r = getRandomInt(1, 6);
    if (r <= (die.hasCrit ? 1 : 0)) return { res: 'crit', dmg: isAtk ? 2 : 1 };
    if (r <= (die.hasCrit ? 1 : 0) + die.hits) return { res: 'hit', dmg: 1 };
    return { res: 'miss', dmg: 0 };
};

const rollPool = (pool: DieConfig[], isAtk: boolean): CombatRollResult => {
    const res: CombatRollResult = { totalDamage: 0, rolls: [] };
    pool.forEach(d => { const { res: r, dmg: dmg } = rollSingleDie(d, isAtk); res.rolls.push(r); res.totalDamage += dmg; });
    return res;
};

export const startAttackRolls = (gs: GameState): { newState: GameState } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const e = ns.enemies.find((en: Enemy) => en.id === ns.combatState.enemyId);
    ns.combatState.playerRolls = rollPool(p.attackDice, true);
    ns.combatState.enemyRolls = rollPool(Array.from({ length: e.level }, (_, i) => ({ id: i, hits: 2, bonusHits: 0, hasCrit: false })), true);
    ns.combatState.combatPhase = 'attack_rolls';
    return { newState: updateCurrentGameState(ns) };
};

export const startDefenseRolls = (gs: GameState): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const e = ns.enemies.find((en: Enemy) => en.id === ns.combatState.enemyId);
    ns.combatState.playerDefenseRolls = rollPool(p.defenseDice, false);
    ns.combatState.enemyDefenseRolls = rollPool(Array.from({ length: e.toughness }, (_, i) => ({ id: i, hits: 2, bonusHits: 0, hasCrit: false })), false);
    ns.combatState.combatPhase = 'defense_rolls';
    return updateCurrentGameState(ns);
};

export const applyCombatResults = (gs: GameState): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const cs = ns.combatState;
    cs.playerDamageTaken = Math.max(0, cs.enemyRolls.totalDamage - cs.playerDefenseRolls.totalDamage);
    cs.enemyDamageTaken = Math.max(0, cs.playerRolls.totalDamage - cs.enemyDefenseRolls.totalDamage);
    cs.combatPhase = 'results_display';
    return updateCurrentGameState(ns);
};

export const resolveCombatRound = (gs: GameState): { newState: GameState, modalInfo: ModalInfo | null } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const e = ns.enemies.find((en: Enemy) => en.id === ns.combatState.enemyId);
    p.hp -= ns.combatState.playerDamageTaken;
    e.hp -= ns.combatState.enemyDamageTaken;
    if (p.hp <= 0) { p.isDead = true; ns.gameStatePhase = 'end_turn'; return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Sconfitto', message: 'Il delirio ti avvolge.' } }; }
    if (e.hp <= 0) {
        ns.enemies = ns.enemies.filter((en: Enemy) => en.id !== e.id);
        p.coins += 20; ns.gameStatePhase = ns.combatState.hasPlayerMoved ? 'end_turn' : 'rolling';
        return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Ricomposto', message: 'L\'anima è libera.' } };
    }
    ns.combatState.combatPhase = 'round_over';
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};

export const endCombatAndTurn = (gs: GameState) => endTurn({ ...gs, gameStatePhase: 'end_turn' });

export const recomposeEnemy = (gs: GameState, eid: number): { newState: GameState, modalInfo: ModalInfo } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const idx = ns.enemies.findIndex((e: Enemy) => e.id === eid);
    const enemy = ns.enemies.splice(idx, 1)[0];
    ns.players[ns.currentPlayerIndex].coins += 30;
    ns.gameStatePhase = 'end_turn';
    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Ricomposto', message: `Hai risvegliato ${enemy.name}.` } };
};

// --- SPELL LOGIC ---
export const castSpell = (gs: GameState, pid: number, sid: string, isCopied = false): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    const spell = p.spells.find((s: MagicSpell) => s.id === sid)!;
    const cost = isCopied ? Math.ceil(spell.costToUse / 2) : spell.costToUse;
    if (p.coins < cost) return { newState: gs, modalInfo: { type: 'info', title: 'Errore', message: 'Intento insufficiente.' } };
    p.coins -= cost; p.hasCastSpellThisTurn = true;

    if (spell.effectTag === 'teleport') {
        p.castingSpellId = sid; ns.gameStatePhase = 'spell_target_cell';
        return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: spell.name, message: 'Scegli una casella.' } };
    }
    if (spell.effectTag === 'hp_to_coins') return { newState: gs, modalInfo: { type: 'hp_sacrifice_choice', title: 'Trasmutazione', spellValue: 4 } };
    if (spell.effectTag === 'reveal_enemy_type') return { newState: gs, modalInfo: { type: 'choose_enemy_type_for_spell', title: 'Percezione', spellId: sid } };

    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Lanciata', message: `Hai usato ${spell.name}` } };
};

export const resolveHPSacrifice = (gs: GameState, amt: number) => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    p.hp -= amt; p.coins += amt * 4; ns.gameStatePhase = 'end_turn';
    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Fatto', message: `Ottenuti ${amt * 4} Intento.` } };
};

export const resolveRevealEnemyType = (gs: GameState, type: KeyColor) => {
    const ns = JSON.parse(JSON.stringify(gs));
    ns.enemies.forEach((e: Enemy) => { if (e.enemyType === type) e.isVisible = true; });
    ns.gameStatePhase = 'end_turn';
    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Rivelati', message: `Incubi ${type} individuati.` } };
};

export const resolveCopySpellChoice = (gs: GameState, accept: boolean) => {
    const ns = JSON.parse(JSON.stringify(gs));
    const state = ns.copySpellState; ns.copySpellState = undefined;
    if (accept) return castSpell(ns, state.copyingPlayerId, state.spell.id, true);
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};

