// --- BOARD ADJACENCY MAP ---
let _boardAdjacency: Record<number, number[]> | null = null;

const getBoardAdjacency = (): Record<number, number[]> => {
    if (_boardAdjacency) return _boardAdjacency;
    const adj: Record<number, number[]> = {};
    const allCellIds = initialBoardLayout.allCells.map(c => c.id).filter(Boolean) as number[];
    for (const id of allCellIds) adj[id] = [];
    for (let i = 1; i <= 48; i++) {
        adj[i].push(i === 1 ? 48 : i - 1, i === 48 ? 1 : i + 1);
    }
    adj[40].push(68); adj[68].push(40);
    adj[16].push(58); adj[58].push(16);
    adj[25].push(67); adj[67].push(25);
    adj[1].push(49); adj[49].push(1);
    [[68, 65], [65, 62], [62, 59], [59, 69], [58, 51], [51, 52], [52, 53], [53, 54], [54, 69], [67, 56], [56, 60], [60, 61], [61, 63], [63, 64], [64, 69], [49, 50], [50, 55], [55, 57], [57, 66], [66, 69]].forEach(([f, t]) => { adj[f].push(t); adj[t].push(f); });
    _boardAdjacency = adj;
    return adj;
};

export const findShortestPath = (startId: number, endId: number, gates: GameState['gates']): number[] | null => {
    if (startId === endId) return [startId];
    const adj = getBoardAdjacency();
    const queue: { cell: number, path: number[] }[] = [{ cell: startId, path: [startId] }];
    const visited = new Set<number>([startId]);
    while (queue.length > 0) {
        const { cell, path } = queue.shift()!;
        if (cell === endId) return path;
        for (const next of adj[cell] || []) {
            if (!visited.has(next)) {
                const isCrossingGate = (Object.values(GATE_CELLS).includes(cell) && !Object.values(GATE_CELLS).includes(next)) || (Object.values(GATE_CELLS).includes(next) && !Object.values(GATE_CELLS).includes(cell));
                if (isCrossingGate) {
                    const gateCell = Object.values(GATE_CELLS).includes(cell) ? cell : next;
                    const color = (Object.keys(GATE_CELLS) as KeyColor[]).find(k => GATE_CELLS[k] === gateCell);
                    if (color && !gates[`${color}Open`]) continue;
                }
                visited.add(next);
                queue.push({ cell: next, path: [...path, next] });
            }
        }
    }
    return null;
};

const calculateDistance = (s: number, e: number, g: GameState['gates']) => (findShortestPath(s, e, g)?.length || Infinity) - 1;

