export const rollDice = (gs: GameState): { newState: GameState, roll: number } => {
    let roll = getRandomInt(1, 6);
    const p = gs.players[gs.currentPlayerIndex];
    if (p.nextRollHalved) { roll = Math.max(1, Math.floor(roll / 2)); p.nextRollHalved = undefined; }
    const ns = { ...JSON.parse(JSON.stringify(gs)), diceResult: roll, gameStatePhase: 'moving' as GamePhase };
    ns.reachableCells = calculateReachableCells(ns);
    return { newState: updateCurrentGameState(ns), roll };
};

const calculateReachableCells = (gs: GameState): number[] => {
    const p = gs.players[gs.currentPlayerIndex];
    const roll = gs.diceResult;
    if (roll === 0) return [];
    const adj = getBoardAdjacency();
    const queue = [{ cell: p.position, dist: 0 }];
    const visited = new Map([[p.position, 0]]);
    const reachable = new Set<number>();
    while (queue.length > 0) {
        const { cell, dist } = queue.shift()!;
        if (dist > 0 && !gs.players.some(op => op.id !== p.id && op.position === cell && !op.isDead)) reachable.add(cell);
        if (dist >= roll) continue;
        for (const next of adj[cell] || []) {
            const isCrossingGate = (Object.values(GATE_CELLS).includes(cell) && !Object.values(GATE_CELLS).includes(next)) || (Object.values(GATE_CELLS).includes(next) && !Object.values(GATE_CELLS).includes(cell));
            if (isCrossingGate) {
                const color = (Object.keys(GATE_CELLS) as KeyColor[]).find(k => GATE_CELLS[k] === (Object.values(GATE_CELLS).includes(cell) ? cell : next));
                if (color && !gs.gates[`${color}Open`]) continue;
            }
            if (!visited.has(next) || visited.get(next)! > dist + 1) { visited.set(next, dist + 1); queue.push({ cell: next, dist: dist + 1 }); }
        }
    }
    return Array.from(reachable);
};

export const initiateCombat = (gs: GameState, enemyId: number, moved: boolean): { newState: GameState, modalInfo: ModalInfo | null } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const enemy = ns.enemies.find((e: Enemy) => e.id === enemyId);
    if (!enemy) return { newState: gs, modalInfo: null };
    enemy.isVisible = true; enemy.hasBeenAttacked = true;
    ns.gameStatePhase = 'combat';
    ns.combatState = { active: true, enemyId, hasPlayerMoved: moved, combatPhase: 'initial', playerRolls: null, enemyRolls: null, playerDefenseRolls: null, enemyDefenseRolls: null, attacksMadeThisTurn: 0, playerDamageTaken: null, enemyDamageTaken: null };
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};

export const endTurn = (gs: GameState): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const oldP = ns.players[ns.currentPlayerIndex];
    oldP.hasNewItem = oldP.hasCastSpellThisTurn = false;
    if (oldP.getsExtraTurn) { oldP.getsExtraTurn = false; ns.gameStatePhase = 'rolling'; return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Turno Extra!', message: 'Entusiasmo!' } }; }

    let nextIdx = (ns.currentPlayerIndex + 1) % ns.players.length;
    while (ns.players[nextIdx].isDead || ns.players[nextIdx].skipNextTurn) {
        if (ns.players[nextIdx].skipNextTurn) ns.players[nextIdx].skipNextTurn = false;
        nextIdx = (nextIdx + 1) % ns.players.length;
    }

    ns.currentPlayerIndex = nextIdx;
    ns.turnNumber += (nextIdx === 0 ? 1 : 0);
    ns.gameStatePhase = 'rolling';
    ns.diceResult = 0;
    ns.reachableCells = null;

    const newP = ns.players[nextIdx];
    if (newP.class === 'sentinella') {
        ns.enemies.forEach((e: Enemy) => { if (!e.isVisible && calculateDistance(newP.position, e.position, ns.gates) <= 2) e.isVisible = true; });
    }

    const enemyOnCell = ns.enemies.find((e: Enemy) => e.position === newP.position);
    if (enemyOnCell) {
        ns.gameStatePhase = 'end_turn';
        return { newState: updateCurrentGameState(ns), modalInfo: { type: 'enemy_encounter', title: 'Incubo!', enemy: enemyOnCell, dialogueRefused: Math.random() < 0.2, hasPlayerMoved: false } };
    }
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};

export const movePlayerAndResolveLanding = (gs: GameState, cellId: number): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string, levelUpInfo: any } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const oldPos = p.position;
    p.position = cellId; ns.gameStatePhase = 'end_turn'; ns.diceResult = 0; ns.reachableCells = null;

    const startPos = PLAYER_START_POSITIONS[p.id];
    if (oldPos < startPos && cellId >= startPos) {
        p.level++; p.maxHp += 5; p.hp = p.maxHp; p.toughness++;
        p.defenseDice.push({ id: p.defenseDice.length, hits: 2, bonusHits: 0, hasCrit: false });
    }

    const enemy = ns.enemies.find((e: Enemy) => e.position === cellId);
    if (enemy) return { newState: updateCurrentGameState(ns), modalInfo: { type: 'enemy_encounter', title: 'Incubo!', enemy, dialogueRefused: Math.random() < 0.2, hasPlayerMoved: true }, levelUpInfo: null };

    return { newState: updateCurrentGameState(ns), modalInfo: null, levelUpInfo: null };
};

// --- SPELL LOGIC ---
export const castSpell = (gs: GameState, pid: number, sid: string, isCopied = false): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    const spell = p.spells.find((s: MagicSpell) => s.id === sid)!;

    // Copy logic check
    if (!isCopied) {
        const copier = ns.players.find((cp: Player) => cp.id !== pid && cp.isCopyingNextSpell);
        if (copier) {
            ns.copySpellState = { spell, castingPlayerId: pid, copyingPlayerId: copier.id };
            return { newState: updateCurrentGameState(ns), modalInfo: { type: 'copy_spell_prompt', title: 'Intuito Mimetico', spell, castingPlayerId: pid, copyingPlayerId: copier.id } };
        }
    }

    const cost = isCopied ? Math.ceil(spell.costToUse / 2) : spell.costToUse;
    if (p.coins < cost) return { newState: gs, modalInfo: { type: 'info', title: 'Errore', message: 'Intento insufficiente.' } };

    p.coins -= cost;
    p.hasCastSpellThisTurn = true;
    let message = `Hai usato ${spell.name}.`;

    switch (spell.effectTag) {
        case 'damage_enemy_dark':
        case 'damage_enemy_white':
        case 'damage_enemy_yellow':
        case 'damage_enemy_red':
        case 'skip_enemy_turn':
            p.castingSpellId = sid;
            ns.gameStatePhase = 'spell_target_enemy';
            return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: spell.name, message: 'Seleziona un incubo sulla mappa.' } };

        case 'teleport':
            p.castingSpellId = sid;
            ns.gameStatePhase = 'spell_target_cell';
            return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: spell.name, message: 'Scegli una casella libera.' } };

        case 'reveal_enemy_type':
            return { newState: gs, modalInfo: { type: 'choose_enemy_type_for_spell', title: 'Percezione Acuita', spellId: sid } };

        case 'hp_to_coins':
            return { newState: gs, modalInfo: { type: 'hp_sacrifice_choice', title: 'Trasmutazione', spellValue: 4 } };

        case 'defend_dark':
        case 'defend_white':
        case 'defend_yellow':
        case 'defend_red':
            p.negateNextDamage = true;
            message += " Sarai protetto dal prossimo danno.";
            break;

        case 'reveal_quest_item':
            if (p.activeQuestId) {
                const quest = offlineQuests.find(q => q.id === p.activeQuestId);
                const item = ns.treasures.find((t: Treasure) => t.itemName === quest?.requiredItemName);
                if (item) { item.isVisible = true; item.visibleUntilTurn = ns.turnNumber + 3; message += " La posizione dell'oggetto è rivelata."; }
            }
            break;

        case 'heal_target':
            p.hp = Math.min(p.maxHp, p.hp + (spell.value || 0));
            message += ` Recuperati ${spell.value} Volontà.`;
            break;

        case 'heal_all':
            ns.players.forEach((pl: Player) => { if(!pl.isDead) pl.hp = Math.min(pl.maxHp, pl.hp + (spell.value || 0)); });
            message += " Tutta la squadra è stata curata.";
            break;

        case 'buff_toughness':
            p.toughness += (spell.value || 0);
            p.defenseDice = Array.from({ length: p.toughness }, (_, i) => ({ id: i, hits: 2, bonusHits: 0, hasCrit: false }));
            message += " Stabilità aumentata permanentemente.";
            break;

        case 'merchant_discount':
            p.nextPurchaseDiscount = (spell.value || 0.3);
            message += " Otterrai uno sconto dal prossimo Genio.";
            break;

        case 'summon_merchant':
            const mId = Date.now();
            const nm: Merchant = { id: mId, name: "Genio Evocato", position: p.position, isVisible: true, pawnImage: preloadedAssets.merchants.defaults[0], stock: generateMerchantStock(ns.merchantStockTier), despawnTurn: ns.turnNumber };
            ns.merchants.push(nm);
            return { newState: updateCurrentGameState(ns), modalInfo: { type: 'merchant', title: 'Genio Evocato', merchant: nm } };

        case 'duplicate_consumable':
            p.willDuplicateNextConsumable = true;
            message += " Il prossimo consumabile trovato sarà duplicato.";
            break;

        case 'copy_spell':
            p.isCopyingNextSpell = true;
            message += " Pronto a copiare la prossima Intenzione alleata.";
            break;
    }

    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Intenzione', message } };
};

export const applySpellEffectToTarget = (gs: GameState, cid: number): { newState: GameState, modalInfo: ModalInfo | null } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const spell = p.spells.find((s: MagicSpell) => s.id === p.castingSpellId);
    if (!spell) return { newState: gs, modalInfo: null };

    p.castingSpellId = undefined;
    ns.gameStatePhase = 'end_turn';
    let message = `Effetto di ${spell.name} applicato.`;

    if (spell.effectTag === 'teleport') {
        p.position = cid;
        message = "Ti sei smaterializzato e riapparso altrove.";
    } else if (spell.effectTag.startsWith('damage_enemy')) {
        const enemy = ns.enemies.find((e: Enemy) => e.position === cid);
        if (enemy) {
            enemy.hp -= (spell.value || 0);
            enemy.hasBeenAttacked = true;
            if (enemy.hp <= 0) {
                ns.enemies = ns.enemies.filter((e: Enemy) => e.id !== enemy.id);
                p.coins += 15;
                message = `Hai ricomposto ${enemy.name}!`;
            } else {
                message = `Inflitti ${spell.value} danni a ${enemy.name}.`;
            }
        }
    } else if (spell.effectTag === 'skip_enemy_turn') {
        const enemy = ns.enemies.find((e: Enemy) => e.position === cid);
        if (enemy) { enemy.skipNextAttack = true; message = `${enemy.name} è caduto in letargia.`; }
    }

    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: spell.name, message } };
};

export const resolveHPSacrifice = (gs: GameState, amt: number) => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    p.hp -= amt; p.coins += amt * 4; ns.gameStatePhase = 'end_turn';
    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Trasmutazione', message: `Ottenuti ${amt * 4} Intento.` } };
};

export const resolveRevealEnemyType = (gs: GameState, type: KeyColor) => {
    const ns = JSON.parse(JSON.stringify(gs));
    ns.enemies.forEach((e: Enemy) => { if (e.enemyType === type) e.isVisible = true; });
    ns.gameStatePhase = 'end_turn';
    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Percezione Acuita', message: `Incubi di tipo ${type} rivelati.` } };
};

export const resolveCopySpellChoice = (gs: GameState, accept: boolean) => {
    const ns = JSON.parse(JSON.stringify(gs));
    const state = ns.copySpellState; 
    const copier = ns.players.find((p: Player) => p.id === state.copyingPlayerId);
    if (copier) copier.isCopyingNextSpell = false;
    ns.copySpellState = undefined;
    if (accept) return castSpell(ns, state.copyingPlayerId, state.spell.id, true);
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};

