export const createInitialGameState = async (playerCount: number = 4, customizations?: PlayerCustomization[], gameMode: GameMode = 'offline'): Promise<GameState> => {
    const playerColors: KeyColor[] = ['black', 'white', 'yellow', 'red'];
    const playersForGame: Player[] = Array.from({ length: playerCount }, (_, i) => {
        const custom = customizations?.[i];
        const pClass = custom?.playerClass || 'guerriero';
        const player: Player = {
            id: i + 1,
            name: custom?.name || `Giocatore ${i + 1}`,
            color: playerColors[i],
            class: pClass,
            controller: custom?.controller || 'human',
            position: PLAYER_START_POSITIONS[i + 1],
            level: 1,
            hp: 20, maxHp: 20,
            toughness: 1,
            isDead: false,
            pawnImage: preloadedAssets.players[pClass][0],
            avatar: preloadedAssets.avatars[playerColors[i]],
            equippedWeapon: createWeaponInstance('d_a_01', 1),
            inventory: [],
            spells: [],
            inventorySize: BASE_INVENTORY_SIZE,
            coins: i === 0 ? 2000 : 10, // DEBUG: 2000 monete al Player 1
            enemiesDefeatedCount: 0,
            keyQuestProgress: 0,
            hasSpawnedMiniBoss: false,
            activeQuestId: null,
            activeQuestHint: null,
            farthestCellReached: PLAYER_START_POSITIONS[i + 1],
            pendingUpgrades: 0,
            attackDice: [],
            defenseDice: [{ id: 0, hits: 2, bonusHits: 0, hasCrit: false }],
        };
        if (player.equippedWeapon) {
            player.attackDice = Array.from({ length: player.equippedWeapon.damageDice }, (_, i) => ({ id: i, hits: 2, bonusHits: 0, hasCrit: false }));
        }

        // DEBUG: Assegna tutte le 20 magie al Giocatore 1
        if (i === 0) {
            player.spells = allMagicSpells.map((s, idx) => ({ ...s, id: `test_${idx}` }));
        }

        return player;
    });

    return {
        ...initialGameState,
        gameMode,
        players: playersForGame,
        enemies: [], // In un test vero dovresti riempire questi array
        npcs: [],
        merchants: [],
        treasures: [],
        worldItems: [],
        specialSquares: []
    };
};

