                            </>
                        ) : (
                            <p>Caricamento dati missione...</p>
                        )}
                    </div>
                </>
            );
        }
        if (isExpanded === 'magic') {
            const spellSlots = [...player.spells];
            // FIX: Ensure empty slots don't become negative during debug testing
            const emptySpellSlotsCount = Math.max(0, MAX_SPELLS - spellSlots.length);

            return (
                <>
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    <div className="magic-inventory-panel" onMouseLeave={() => setHoveredItem(null)}>
                        <h4>Intenzioni</h4>
                        <div className={`inventory-grid inventory-grid-${MAX_SPELLS}`} style={{maxHeight: '200px', overflowY: 'auto'}}>
                            {spellSlots.map((spell) => {
                                const displayInfo = getDisplayInfoForItem(spell);
                                const canCast = player.coins >= spell.costToUse;
                                const isCastDisabled = !canCast || player.hasCastSpellThisTurn;

                                const getTitle = () => {
                                    if (player.hasCastSpellThisTurn) return "Hai già lanciato un'intenzione in questo turno.";
                                    if (!canCast) return `Intento insufficiente (${player.coins}/${spell.costToUse})`;
                                    return spell.name;
                                };

                                const contextMenuOptions = [{
                                    label: 'Lancia Intenzione',
                                    action: () => onCastSpell(player.id, spell.id),
                                    disabled: isCastDisabled
                                }];

                                return (
                                    <div key={spell.id} className="inventory-slot-wrapper clickable"
                                        onContextMenu={(e) => openContextMenu(e, contextMenuOptions)}
                                        onMouseEnter={() => setHoveredItem(spell)}
                                        title={getTitle()}
                                    >
                                        <div className="slot-level-indicator-container" />
                                        <div className={`inventory-slot magic-slot ${isCastDisabled ? 'disabled' : ''}`}>
                                            <img src={displayInfo.image} alt={displayInfo.name} />
                                        </div>
                                    </div>
                                );
                            })}
                            {Array.from({ length: emptySpellSlotsCount }).map((_, index) => (
                                <div key={`empty-spell-slot-${index}`} className="inventory-slot-wrapper">
                                    <div className="slot-level-indicator-container" />
                                    <div className="inventory-slot empty" />
                                </div>
                            ))}
                        </div>
                         <div className="weapon-preview-panel">
                            {hoveredItem && hoveredItem.type === 'intention' ? (() => {
                                const spell = hoveredItem as MagicSpell;
                                return (
                                    <>
                                        <h4>{spell.name}</h4>
                                        <strong>Costo: {spell.costToUse} Intento</strong>
                                        <p className="weapon-effect-description">{spell.description}</p>
                                    </>
                                )
                            })() : (
                                <p className="preview-placeholder">Passa il mouse su un'intenzione per i dettagli.</p>
                            )}
                        </div>
                    </div>
                </>
            );
        }
        if (isExpanded === 'inventory') {
            const inventoryItems = [...player.inventory];
            const emptySlotsCount = player.inventorySize - inventoryItems.length;

            return (
                <>
                    {renderPlayerCardHeader()}
                    <HealthBar currentHp={player.hp} maxHp={player.maxHp} />
                    <IntentBar currentIntent={player.coins} />
                    {renderEquippedWeaponDisplay()}
                    <div className="dice-pools-container">
                        <DicePoolDisplay dice={player.attackDice} title="Arm." playerColor={playerColorHex[player.color]} />
                        <DicePoolDisplay dice={player.defenseDice} title="Stab." playerColor={playerColorHex[player.color]} />
                    </div>
                    <div className={`inventory-grid inventory-grid-${player.inventorySize}`} onMouseLeave={() => setHoveredItem(null)}>
                        {inventoryItems.map((item, index) => {
                            const isWeapon = item.type === 'melee' || item.type === 'ranged' || item.type === 'magic';
                            const isConsumable = item.type === 'potion' || item.type === 'spellScroll' || item.type === 'bag';

                            const contextMenuOptions = [];
                            if (!player.isDead) {
                                if (isWeapon) {
                                    contextMenuOptions.push({ label: 'Equipaggia', action: () => onEquipWeapon(player.id, index) });
                                }
                                if (isConsumable) {
                                    contextMenuOptions.push({ label: 'Usa', action: () => onUseConsumable(player.id, index) });
                                }
                                contextMenuOptions.push({ label: 'Lascia', action: () => onDropWeapon(player.id, index) });
                            }
                             const displayInfo = getDisplayInfoForItem(item);
                            return (
                                <div key={item.id || `item-${index}`} className={`inventory-slot-wrapper clickable`}
                                    onContextMenu={(e) => {
                                        if (contextMenuOptions.length > 0) {
                                            openContextMenu(e, contextMenuOptions);
                                        }
                                    }}
                                    onMouseEnter={() => setHoveredItem(item)}>
                                    <div className="slot-level-indicator-container">
                                        {displayInfo.level !== null && (<span className="slot-level-indicator">Liv: {displayInfo.level}</span>)}
                                    </div>
                                    <div className="inventory-slot">
                                        <img src={displayInfo.image} alt={displayInfo.name} title={displayInfo.name} />
                                    </div>
                                </div>
                            );
                        })}
                        {Array.from({ length: emptySlotsCount }).map((_, index) => (
                            <div key={`empty-slot-${index}`} className="inventory-slot-wrapper">
                                <div className="slot-level-indicator-container" />
                                <div className="inventory-slot empty" />
                            </div>
                        ))}
                    </div>
                    <div className="weapon-preview-panel">
                        {hoveredItem ? (() => {
                             const info = getDisplayInfoForItem(hoveredItem);
                            if (hoveredItem.type === 'intention') {
                                const spell = hoveredItem as MagicSpell;
                                 return <><h4>{info.name}</h4><strong>Costo Acquisto: {spell.costToBuy} Intento</strong><p className="weapon-effect-description">{info.description}</p></>;
                            }
                            const isWeapon = hoveredItem.type === 'melee' || hoveredItem.type === 'ranged' || hoveredItem.type === 'magic';
                            return (
                                <>
                                    <h4>{info.name} {info.level !== null ? `(Liv: ${info.level})` : ''}</h4>
                                    {isWeapon && <strong>"{(hoveredItem as Weapon).bonusEffect.name}"</strong>}
                                    <p className="weapon-effect-description">{info.description}</p>
                                </>
                            )
                        })() : (
                            <p className="preview-placeholder">Passa il mouse su un oggetto per i dettagli.</p>
                        )}
                    </div>
                </>
            );
        }
        return null;
    };

    return (
        <div className="player-stat-card" style={{ borderColor: playerColorHex[player.color] }} onClick={() => onClick(player.id)}>
            {player.hasNewItem && <div className="new-item-indicator" title="Nuovo oggetto nell'inventario!">🎒</div>}
            {renderContent()}
        </div>
    );
};


const App = () => {
  // Dimensioni per le miniature (player, nemici, etc.)
  const PAWN_WIDTH = 40;
  const PAWN_HEIGHT = 40;
  // Dimensioni per le icone (tesori, armi, etc.)
  const ICON_WIDTH = 20;
  const ICON_HEIGHT = 20;
  const PAWN_ANIMATION_SPEED = 200; // ms per casella
  const AI_THINK_DELAY = 1500; // ms

  const [view, setView] = useState<'splash' | 'selection' | 'loading' | 'game'>('splash');
  const [gameState, setGameState] = useState<GameState>(initialGameState);
  const [gameSettings, setGameSettings] = useState<GameSettings | null>(null);
  const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);
  const [ghostPawnPosition, setGhostPawnPosition] = useState<number | null>(null);
  const [modalInfo, setModalInfo] = useState<ModalInfo | null>(null);
  const [isModalClosing, setIsModalClosing] = useState(false);
  const [expansionState, setExpansionState] = useState<Record<number, 'equipped' | 'inventory' | 'quest' | 'magic'>>({});
  const [contextMenuInfo, setContextMenuInfo] = useState<ContextMenuProps | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isUpgradeModalOpen, setIsUpgradeModalOpen] = useState(false);
  const [toastInfo, setToastInfo] = useState<{ message: string; id: number } | null>(null);
  const previousKeysRef = useRef<GameState['keys']>(gameState.keys); // for key notifications
  const previousTrustLevelRef = useRef<string>(gameState.trustLevel); // for trust notifications

  // --- STATO PER ANIMAZIONE ---
  const [isAnimating, setIsAnimating] = useState(false); // Usato per animazioni di movimento e turni IA
  const [pawnVisualPositions, setPawnVisualPositions] = useState<PawnVisualPositions>({});
  const [isGameReady, setIsGameReady] = useState(false);


  // --- Board Dimensions & Cells ---
  const { allCells, viewBoxWidth, viewBoxHeight, PADDING, getCellCoordinatesById } = gameEngine.boardLayout;

  const playerColorHex: Record<string, string> = {
    red: '#c0392b',
    yellow: '#f1c40f',
    white: '#aeb6bf',
    black: '#2c3e50',
  };


  // --- App Flow ---
  const handleSplashClick = () => {
    document.documentElement.requestFullscreen().catch(err => {
        console.warn(`Errore nell'attivare la modalità schermo intero: ${err.message} (${err.name})`);
    });
    // Initialize AudioContext on first user interaction
    AudioManager.initialize();
    setView('selection');
  };

  const handleSettingsConfirm = (settings: GameSettings) => {
    AudioManager.setAudioEnabled(settings.audio);
    setGameSettings(settings);
    setIsCustomizeModalOpen(true);
  };

  const handleGameStart = async (customizations: PlayerCustomization[]) => {
      if (!gameSettings) return;
      setIsCustomizeModalOpen(false);
      setView('loading');

      try {
        const newGameState = await createInitialGameState(gameSettings.players, customizations, gameSettings.mode);
        setGameState(newGameState);
        setView('game');
      } catch (error) {
          console.error("Failed to initialize game:", error);
          alert("Could not start the game. The AI service may be unavailable. Please try again or play in offline mode.");
          setView('selection');
      }
  };

    const pawnPositionsSignature = useMemo(() => {
        const allPawns = [...gameState.players, ...gameState.enemies, ...gameState.merchants, ...gameState.npcs];
        allPawns.sort((a, b) => a.id - b.id); // Assicura un ordine stabile per la stringa
        return JSON.stringify(allPawns.map(p => ({ id: p.id, pos: p.position })));
    }, [gameState]);


    // Helper function to generate a unique key for any pawn-like entity.
    const getPawnKey = (pawn: any): string => {
        if ('color' in pawn) return `player_${pawn.id}`; // Player
        if ('stock' in pawn) return `merchant_${pawn.id}`; // Merchant
        if ('quest' in pawn) return `npc_${pawn.id}`; // NPC
        if ('hp' in pawn && !('color' in pawn)) return `enemy_${pawn.id}`; // Enemy
        return `unknown_${pawn.id}`; // Fallback
    };

  // --- Inizializzazione e Sincronizzazione delle Posizioni Visive ---
    useEffect(() => {
        const newVisuals: PawnVisualPositions = {};

        // 1. Raggruppa tutte le miniature visibili per cella
        const pawnsByCell = new Map<number, any[]>();
        const allVisiblePawns = [
            ...gameState.players,
            ...gameState.enemies.filter(e => e.isVisible),
            ...gameState.merchants.filter(m => m.isVisible),
            ...gameState.npcs.filter(n => n.isVisible),
        ];

        allVisiblePawns.forEach(pawn => {
            const pos = pawn.position;
            if (!pawnsByCell.has(pos)) pawnsByCell.set(pos, []);
            pawnsByCell.get(pos)!.push(pawn);
        });

        // Helper to get corner positions based on the number of pawns
        const getCornerPositions = (cellCoords: { x: number, y: number, width: number, height: number }, count: number, pawnWidth: number, pawnHeight: number) => {
            const positions: { x: number, y: number }[] = [];
            const { x, y, width, height } = cellCoords;
            const topLeft = { x: x, y: y };
            const topRight = { x: x + width - pawnWidth, y: y };
            const bottomLeft = { x: x, y: y + height - pawnHeight };
            const bottomRight = { x: x + width - pawnWidth, y: y + height - pawnHeight };

            switch (count) {
                case 2:
                    positions.push(topLeft, bottomRight); // Diagonale
                    break;
                case 3:
                    positions.push(topLeft, topRight, bottomLeft); // a L
                    break;
                case 4:
                default: // Gestisce 4 o più pedine
                    positions.push(topLeft, topRight, bottomLeft, bottomRight);
                    break;
            }
            return positions;
        };

        // 2. Itera su ogni cella e calcola il layout
        pawnsByCell.forEach((pawnsOnCell, cellId) => {
            const coords = getCellCoordinatesById(cellId);
            if (!coords) return;

            if (pawnsOnCell.length > 1) {
                // Più di una miniatura: ridimensiona e posiziona negli angoli
                const newWidth = PAWN_WIDTH / 2;
                const newHeight = PAWN_HEIGHT / 2;
                const cornerPositions = getCornerPositions(coords, pawnsOnCell.length, newWidth, newHeight);

                pawnsOnCell.forEach((pawn, index) => {
                    const key = getPawnKey(pawn);
                    const pos = cornerPositions[index % 4]; // Usa modulo per gestire più di 4 pedine
                    newVisuals[key] = {
                        x: pos.x,
                        y: pos.y,
                        width: newWidth,
                        height: newHeight,
                    };
                });
            } else {
                // Una sola miniatura: posiziona al centro a dimensione intera
                const pawn = pawnsOnCell[0];
                const key = getPawnKey(pawn);
                newVisuals[key] = {
                    x: coords.x + (coords.width - PAWN_WIDTH) / 2,
                    y: coords.y + (coords.height - PAWN_HEIGHT) / 2 - 10,
                    width: PAWN_WIDTH,
                    height: PAWN_HEIGHT,
                };
            }
        });

        setPawnVisualPositions(newVisuals);

    }, [pawnPositionsSignature, getCellCoordinatesById]);


  // --- Helper Functions ---
  const getEntityKey = (entity: any) => `${entity.name}_${entity.id}`;

  const getEntityType = (entity: any): 'pawn' | 'icon' => {
      // Players, Enemies, Merchants, NPCs are 'pawns' (miniatures)
      if ('color' in entity || 'hp' in entity || 'quest' in entity || (entity.name && entity.name.startsWith('Genio'))) {
          return 'pawn';
      }
      // Treasures, WorldItems, SpecialSquares are 'icons'
      return 'icon';
  };

  const allEntitiesToRender = gameEngine.getVisibleEntities(gameState);
  const pawnsToRender = allEntitiesToRender.filter(e => getEntityType(e) === 'pawn');
  const iconsToRender = allEntitiesToRender.filter(e => getEntityType(e) === 'icon');

  // Ordina le pedine in base alla coordinata Y per garantire un corretto ordine di sovrapposizione
  const sortedPawnsToRender = useMemo(() => {
      return [...pawnsToRender].sort((a, b) => {
          const keyA = getPawnKey(a);
          const keyB = getPawnKey(b);
          const visualA = pawnVisualPositions[keyA];
          const visualB = pawnVisualPositions[keyB];

          if (!visualA || !visualB) {
              return 0; // Non ordinare se le informazioni visive non sono pronte
          }

          // Ordinamento primario per coordinata y
          if (visualA.y !== visualB.y) {
              return visualA.y - visualB.y;
          }

          // Ordinamento secondario per pedine allo stesso livello y (opzionale ma stabile)
          return visualA.x - visualB.x;
      });
  }, [pawnsToRender, pawnVisualPositions]);


  // --- Game Actions ---
  const handleRollDice = async () => {
    const currentPlayer = gameState.players[gameState.currentPlayerIndex];
    if (currentPlayer.isDead || isAnimating || currentPlayer.controller === 'ai') return;

    setGameState(gs => {
        const { newState, roll } = gameEngine.rollDice(gs);
        showDiceRoll([roll], `Lancio per ${currentPlayer.name}...`, playerColorHex[currentPlayer.color]);
        return newState;
    });
  };

  const handleEndTurn = () => {
    if (isAnimating) return;
    setGameState(gs => {
        const { newState, modalInfo: turnModal, audioAnnouncement } = gameEngine.endTurn(gs);
        if (turnModal) {
            setModalInfo(turnModal);
        }
        if (audioAnnouncement) {
            AudioManager.playAnnouncement(audioAnnouncement);
        }
        return newState;
    });
    setExpansionState({});
  };

  const animatePawnAlongPath = (path: number[], finalTargetId: number) => {
    let currentStep = 0;
    const playerKey = getPawnKey(gameState.players[gameState.currentPlayerIndex]);

    const moveNext = () => {
      if (currentStep >= path.length) {
        // Animation finished, now resolve the landing
        setGameState(gs => {
            const { newState, modalInfo: landingModalInfo, audioAnnouncement, levelUpInfo } = gameEngine.movePlayerAndResolveLanding(gs, finalTargetId);
            if (landingModalInfo) {
              if (audioAnnouncement) {
                AudioManager.playAnnouncement(audioAnnouncement);
              }
              setModalInfo(landingModalInfo);
            } else if (audioAnnouncement) {
              AudioManager.playAnnouncement(audioAnnouncement);
            }
            if (levelUpInfo) {
                setToastInfo({ message: `${levelUpInfo.playerName} è salito al Livello ${levelUpInfo.newLevel}!`, id: Date.now() });
            }
            return newState;
        });
        setIsAnimating(false);
        return;
      }

      const nextCellId = path[currentStep];
      const coords = getCellCoordinatesById(nextCellId);
      if (coords) {
        setPawnVisualPositions(prev => ({
          ...prev,
          [playerKey]: {
            ...prev[playerKey],
            x: coords.x + (coords.width - PAWN_WIDTH) / 2,
            y: coords.y + (coords.height - PAWN_HEIGHT) / 2 - 10,
          }
        }));
      }

      currentStep++;
      setTimeout(moveNext, PAWN_ANIMATION_SPEED);
    };

    moveNext();
  };

  const currentPlayer = gameState.players[gameState.currentPlayerIndex];

  const handleCellClick = (cellId: number | undefined) => {
    if (!cellId || isAnimating) return;

    if (gameState.gameStatePhase === 'spell_target_enemy' || gameState.gameStatePhase === 'spell_target_cell') {
        if (gameEngine.isMoveValid(gameState, cellId)) {
            setGameState(gs => {
                const { newState, modalInfo, audioAnnouncement } = gameEngine.applySpellEffectToTarget(gs, cellId);
                if (modalInfo) setModalInfo(modalInfo);
                if (audioAnnouncement) AudioManager.playAnnouncement(audioAnnouncement);
                return newState;
            });
            setGhostPawnPosition(null);
        }
        return;
    }

    if (gameState.gameStatePhase === 'cell_inspection') {
        setGameState(gs => gameEngine.inspectCell(gs, cellId));
        closeModal();
        return;
    }

    if (Object.values(PLAYER_START_POSITIONS).includes(cellId)) {
        setModalInfo({
            type: 'shared_stash',
            title: 'Cassa Condivisa della Squadra',
        });
        return;
    }

    if (!gameEngine.isMoveValid(gameState, cellId)) return;

    setGhostPawnPosition(null);
    setIsAnimating(true);

    const path = gameEngine.findShortestPath(currentPlayer.position, cellId, gameState.gates);

    if (path) {
        animatePawnAlongPath(path, cellId);
    } else {
        // Fallback to teleport if path not found (shouldn't happen for valid moves)
        setGameState(gs => {
            const { newState, modalInfo: landingModalInfo, audioAnnouncement, levelUpInfo } = gameEngine.movePlayerAndResolveLanding(gs, cellId);
            if (landingModalInfo) {
              if (audioAnnouncement) {
                AudioManager.playAnnouncement(audioAnnouncement);
              }
              setModalInfo(landingModalInfo);
            } else if (audioAnnouncement) {
              AudioManager.playAnnouncement(audioAnnouncement);
            }
            if (levelUpInfo) {
                setToastInfo({ message: `${levelUpInfo.playerName} è salito al Livello ${levelUpInfo.newLevel}!`, id: Date.now() });
            }
            return newState;
        });
        setIsAnimating(false);
    }
  };

  const handleCellMouseEnter = (cellId: number | undefined) => {
    if (cellId && (gameEngine.isMoveValid(gameState, cellId) || gameState.gameStatePhase === 'cell_inspection')) {
      setGhostPawnPosition(cellId);
    } else {
      setGhostPawnPosition(null);
    }
  };

  const handleCellMouseLeave = () => {
    setGhostPawnPosition(null);
  };

  const closeModal = () => {
    if (isModalClosing) return;

    setIsModalClosing(true);
    setTimeout(() => {
        if (modalInfo && ['loot_choice', 'merchant', 'quest_offer', 'mage_encounter', 'swap_confirmation', 'titan_encounter', 'dialogue', 'enemy_encounter', 'treasure_reveal', 'special_square_reveal', 'choose_enemy_type_for_spell', 'hp_sacrifice_choice', 'copy_spell_prompt'].includes(modalInfo.type)) {
            setGameState(gs => ({ ...gs, gameStatePhase: 'end_turn' }));
        }
        setModalInfo(null);
        setIsModalClosing(false);
    }, 300); // Match CSS animation duration
  };

  const handlePlayerCardClick = (playerId: number) => {
    const isOpeningInventory = !expansionState[playerId] || expansionState[playerId] === 'equipped';

    if (isOpeningInventory) {
        setGameState(gs => {
            const newPlayers = [...gs.players];
            const player = newPlayers.find(p => p.id === playerId);
            if (player) {
                player.hasNewItem = false;
            }
            return { ...gs, players: newPlayers };
        });
    }

    setExpansionState(prev => {
        const currentLevel = prev[playerId];
        if (!currentLevel) return { [playerId]: 'equipped' };
        if (currentLevel === 'equipped') return { [playerId]: 'inventory' };
        return {};
    });
  };

  const handleQuestIconClick = (e: React.MouseEvent, playerId: number) => {
    e.stopPropagation(); 
    setExpansionState(prev => {
        if (prev[playerId] === 'quest') return {};
        return { [playerId]: 'quest' };
    });
  };

  const handleMagicIconClick = (e: React.MouseEvent, playerId: number) => {
    e.stopPropagation();
    setExpansionState(prev => {
        if (prev[playerId] === 'magic') return {};
        return { [playerId]: 'magic' };
    });
  };

  const handleLootItemSelect = (item: gameEngine.WorldItem) => {
    setGameState(gs => {
      const { newState, modalInfo } = gameEngine.pickUpWorldItem(gs, item.id);
      if (modalInfo) {
        setModalInfo(modalInfo);
      }
      return newState;
    });
  };

  const handleLootAll = () => {
      setGameState(gs => gameEngine.pickUpAllLoot(gs));
  };

  const handleSwapConfirm = (itemId: string) => {
      setGameState(gs => gameEngine.swapWeaponWithWorldItem(gs, itemId));
      setModalInfo(null);
  };

  const handlePurchaseItem = (item: Weapon | Consumable | MagicSpell, merchantId: number) => {
    setGameState(gs => {
        const { newState, success, message } = gameEngine.purchaseItemFromMerchant(gs, item, merchantId);
        setModalInfo({
            type: 'info',
            title: success ? 'Acquisto Effettuato' : 'Acquisto Fallito',
            message: message
        });
        return newState;
    });
  };

  const handleToggleFullscreen = () => {
      if (!document.fullscreenElement) {
          document.documentElement.requestFullscreen().catch(err => {
              alert(`Errore nell'attivare la modalità schermo intero: ${err.message} (${err.name})`);
          });
      } else {
          if (document.exitFullscreen) {
              document.exitFullscreen();
          }
      }
  };

  const handleAcceptQuest = (npcId: number) => {
    setGameState(gs => {
        const { newState, modalInfo: resultModal, audioAnnouncement } = gameEngine.acceptQuest(gs, npcId);
        setModalInfo(resultModal);
        if (audioAnnouncement) {
            AudioManager.playAnnouncement(audioAnnouncement);
        }
        return newState;
    });
  };

  const handleApplyDiceUpgrade = (type: 'attack' | 'defense', dieId: number, upgradeType: 'add_hit' | 'promote_crit') => {
    setGameState(gs => gameEngine.applyDiceUpgrade(gs, type, dieId, upgradeType));
    const player = gameEngine.getLatestState().players[gameState.currentPlayerIndex];
    if (player.pendingUpgrades === 0) {
        setIsUpgradeModalOpen(false);
    }
  };

  const handleEngageTitan = () => {
    setModalInfo(null);
    setGameState(gs => {
        const { newState } = gameEngine.engageWanderingTitan(gs);
        return newState;
    });
  };

    const handleDialogueChoice = (enemyId: number, choice: 'talk' | 'fight') => {
        if (choice === 'fight') {
            setGameState(gs => {
                if (modalInfo?.type === 'dialogue') {
                    // FIX: Removed extra argument 'dialogue_abandon' from initiateCombat call.
                    const { newState } = gameEngine.initiateCombat(gs, enemyId, modalInfo.hasPlayerMoved);
                    return newState;
                }
                return gs;
            });
        }
        // La logica per 'talk' è gestita all'interno di DialogueModalContent
    };

    const handleDialogueFailure = (enemyId: number) => {
        setGameState(gs => {
            if (modalInfo?.type === 'dialogue') {
                const { newState, modalInfo: resultModal } = gameEngine.handleDialogueFailure(gs, enemyId, modalInfo.hasPlayerMoved);
                setModalInfo(resultModal);
                return newState;
            }
            return gs;
        });
    };


  // --- Combat Actions ---
  const handleStartAttackRolls = () => {
    setGameState(gs => {
        if(modalInfo?.type === 'mage_encounter' && modalInfo.enemy){
            const { newState: initiatedState } = gameEngine.initiateCombat(gs, modalInfo.enemy.id, true);
            const { newState: finalState } = gameEngine.startAttackRolls(initiatedState);
            return finalState;
        }
        const { newState } = gameEngine.startAttackRolls(gs);
        return newState;
    });
  };

  const handleStartDefenseRolls = () => {
    setGameState(gs => gameEngine.startDefenseRolls(gs));
  };

  const handleApplyCombatResults = () => {
    setGameState(gs => gameEngine.applyCombatResults(gs));
  };

  const handleResolveCombatRound = () => {
     setGameState(gs => {
        const { newState, modalInfo: resultModal } = gameEngine.resolveCombatRound(gs);
        if (resultModal) {
          setModalInfo(resultModal);
        }
        return newState;
    });
  };

  const handleEndCombatTurn = () => {
    setGameState(gs => {
        const {newState, modalInfo: endTurnModal } = gameEngine.endCombatAndTurn(gs);
        if(endTurnModal){
            setModalInfo(endTurnModal);
        } else {
            setModalInfo(null);
        }
        return newState;
    });
  };

  const handleFlee = (hasPlayerMoved: boolean) => {
      setGameState(gs => {
          const { newState, modalInfo: resultModal } = gameEngine.attemptFlee(gs, hasPlayerMoved);
          setModalInfo(resultModal);
          return newState;
      });
  };

  // --- Stash Actions ---
    const handleDepositItem = (inventoryIndex: number) => {
        setGameState(gs => gameEngine.depositToStash(gs, inventoryIndex));
    };

    const handleWithdrawItem = (stashIndex: number) => {
        setGameState(gs => gameEngine.withdrawFromStash(gs, stashIndex));
    };

    const handleMoveItem = (source: gameEngine.ItemLocation, destination: gameEngine.ItemLocation) => {
        setGameState(gs => gameEngine.moveItem(gs, source, destination));
    };

    // --- Consumable Actions ---
    const handleUseConsumable = (playerId: number, inventoryIndex: number) => {
        setGameState(gs => {
            const { newState, modalInfo: resultModal, audioAnnouncement } = gameEngine.useConsumable(gs, playerId, inventoryIndex);
            if (resultModal) {
                setModalInfo(resultModal);
            }
            if (audioAnnouncement) {
                AudioManager.playAnnouncement(audioAnnouncement);
            }
            return newState;
        });
    };

    // --- Magic Spell Actions ---
    const handleCastSpell = (playerId: number, spellId: string) => {
        setGameState(gs => {
            const { newState, modalInfo: resultModal, audioAnnouncement } = gameEngine.castSpell(gs, playerId, spellId);
             if (resultModal) {
                setModalInfo(resultModal);
            }
            if (audioAnnouncement) {
                AudioManager.playAnnouncement(audioAnnouncement);
            }
            return newState;
        });
    };

    const handleHPSacrifice = (amount: number) => {
        setGameState(gs => {
            const { newState, modalInfo } = gameEngine.resolveHPSacrifice(gs, amount);
            setModalInfo(modalInfo);
            return newState;
        });
    };

    const handleRevealTypeChoice = (type: KeyColor) => {
        setGameState(gs => {
            const { newState, modalInfo } = gameEngine.resolveRevealEnemyType(gs, type);
            setModalInfo(modalInfo);
            return newState;
        });
    };

    const handleCopySpellChoice = (accept: boolean) => {
        setGameState(gs => {
            const { newState, modalInfo } = gameEngine.resolveCopySpellChoice(gs, accept);
            if (modalInfo) setModalInfo(modalInfo);
            return newState;
        });
    };

    // --- Encounter Actions ---
    const handleChooseToTalk = (enemy: Enemy, hasPlayerMoved: boolean) => {
        setModalInfo({ type: 'dialogue', title: `Parli con ${enemy.name}`, enemy, hasPlayerMoved });
    };

    const handleChooseToFight = (enemy: Enemy, hasPlayerMoved: boolean) => {
        setGameState(gs => {
            const { newState } = gameEngine.initiateCombat(gs, enemy.id, hasPlayerMoved);
            return newState;
        });
        setModalInfo(null);
    };


  // Effect to manage combat start and updates
  useEffect(() => {
    if (gameState.gameStatePhase === 'combat' && gameState.combatState.active) {
      const enemy = gameState.enemies.find(e => e.id === gameState.combatState.enemyId);
      if (!enemy) return;

      setModalInfo(prevModal => {
        // Aggiorna o crea la modale di combattimento
        if (prevModal?.type === 'combat' && prevModal.enemy?.id === enemy.id) {
            return { ...prevModal, enemy: enemy };
        }
        return {
            type: 'combat',
            title: 'Entrare in Risonanza!',
            enemy: enemy,
            isContinuation: !gameState.combatState.hasPlayerMoved,
        };
      });
    } else if (
        gameState.gameStatePhase !== 'combat' && 
        gameState.gameStatePhase !== 'dialogue' && 
        modalInfo && (modalInfo.type === 'combat' || modalInfo.type === 'mage_encounter' || modalInfo.type === 'dialogue')
    ) {
        // Chiudi la modale se non siamo più in una fase che la richiede
        setModalInfo(null);
    }
  }, [gameState.gameStatePhase, gameState.combatState.active, gameState.combatState.enemyId, gameState.enemies]);

    // Effect to check for Game Over
    useEffect(() => {
        const allPlayersDead = gameState.players.every(p => p.isDead);
        if (allPlayersDead && gameState.players.length > 0 && modalInfo?.title !== 'Game Over') {
            const gameOverMessage = 'Tutti i giocatori sono stati sconfitti!';
            setModalInfo({ type: 'info', title: 'Game Over', message: gameOverMessage });
            AudioManager.playAnnouncement(gameOverMessage);
        }
    }, [gameState.players, modalInfo]);

    // Effect for Victory
    useEffect(() => {
        if (gameState.gameStatePhase === 'gameOver' && modalInfo?.title !== 'Vittoria!') {
            const winner = gameState.players.find(p => p.id === gameState.winner);
            const message = winner ? `La squadra ha vinto! ${winner.name} ha sferrato il colpo di grazia!` : 'La squadra ha trionfato!';
            setModalInfo({ type: 'info', title: 'Vittoria!', message: message });
            AudioManager.playAnnouncement(message);
        }
    }, [gameState.gameStatePhase, gameState.winner, modalInfo]);

    // Effect to track fullscreen state
    useEffect(() => {
        const onFullscreenChange = () => setIsFullscreen(!!document.fullscreenElement);
        document.addEventListener('fullscreenchange', onFullscreenChange);
        return () => document.removeEventListener('fullscreenchange', onFullscreenChange);
    }, []);

    // Effect to enable animations after initial game load
    useEffect(() => {
        if (view === 'game') {
            const timer = setTimeout(() => setIsGameReady(true), 50);
            return () => clearTimeout(timer);
        } else {
            setIsGameReady(false);
        }
    }, [view]);

    // Effect to sync the loot modal after an item has been picked up.
    useEffect(() => {
        if (modalInfo?.type === 'loot_choice') {
            const currentPlayer = gameState.players[gameState.currentPlayerIndex];
            const itemsOnCell = gameState.worldItems.filter(item => item.position === currentPlayer.position && item.isVisible);
            if (itemsOnCell.length !== modalInfo.items?.length) {
                if (itemsOnCell.length > 0) {
                    setModalInfo(prev => ({ ...prev!, type: 'loot_choice', items: itemsOnCell }));
                } else {
                    closeModal(); // Close modal if all items are gone
                }
            }
        }
    }, [gameState.worldItems, modalInfo, gameState.players, gameState.currentPlayerIndex]);

    useEffect(() => {
        // Sync quest offer modal when AI generates quest
        if (modalInfo?.type === 'quest_offer') {
            const freshNpc = gameState.npcs.find(n => n.id === modalInfo.npc.id);
            // If the quest ID has changed from PENDING to a real ID, update the modal
            if (freshNpc && freshNpc.quest.id !== modalInfo.npc.quest.id) {
                setModalInfo({
                    ...modalInfo,
                    npc: freshNpc 
                });
            }
        }
    }, [gameState.npcs, modalInfo]);

     // --- AI TURN MANAGEMENT ---
    useEffect(() => {
        if (view !== 'game' || !currentPlayer || currentPlayer.controller !== 'ai' || gameState.gameStatePhase !== 'rolling' || isAnimating) {
            return;
        }

        const executeAITurn = async () => {
            setGameState(gs => ({ ...gs, gameStatePhase: 'ai_turn' }));
            setIsAnimating(true);
            await new Promise(resolve => setTimeout(resolve, AI_THINK_DELAY));

            let rolledState: GameState;
            let roll: number;
            setGameState(gs => {
                const result = gameEngine.rollDice(gs);
                rolledState = result.newState;
                roll = result.roll;
                return result.newState;
            });
            await showDiceRoll([roll!], `L'IA ${rolledState!.players[rolledState!.currentPlayerIndex].name} lancia il dado...`, playerColorHex[rolledState!.players[rolledState!.currentPlayerIndex].color]);
            await new Promise(resolve => setTimeout(resolve, 500));

            const action = gameEngine.calculateAIMove(rolledState!);
            if (action.type === 'move') {
                const path = gameEngine.findShortestPath(rolledState!.players[rolledState!.currentPlayerIndex].position, action.targetCellId, rolledState!.gates);
                if (path) {
                    animatePawnAlongPath(path, action.targetCellId);
                } else {
                     handleEndTurn();
                     setIsAnimating(false);
                }
            } else if (action.type === 'use_consumable') {
                handleUseConsumable(rolledState!.players[rolledState!.currentPlayerIndex].id, action.inventoryIndex);
                setGameState(gs => ({...gs, gameStatePhase: 'end_turn'}));
                setIsAnimating(false);
            } else if (action.type === 'attack') {
                handleStartAttackRolls();
            } else { // 'end_turn'
                 handleEndTurn();
                 setIsAnimating(false);
            }
        };
        executeAITurn();
    }, [gameState.currentPlayerIndex, gameState.gameStatePhase, isAnimating, view, currentPlayer]);


    // Effect to automatically end AI turn after it has moved or acted
    useEffect(() => {
        if (!currentPlayer || currentPlayer.controller !== 'ai' || gameState.gameStatePhase !== 'end_turn' || isAnimating) {
            return;
        }

        const isInteractiveModal = modalInfo && ['loot_choice', 'swap_confirmation', 'merchant', 'quest_offer', 'mage_encounter', 'titan_encounter', 'dialogue', 'enemy_encounter', 'treasure_reveal', 'special_square_reveal', 'choose_enemy_type_for_spell', 'hp_sacrifice_choice', 'copy_spell_prompt'].includes(modalInfo.type);
        const timer = setTimeout(() => {
            if (modalInfo) closeModal();
            handleEndTurn();
        }, isInteractiveModal ? 50 : 1200);
        return () => clearTimeout(timer);
    }, [gameState.gameStatePhase, isAnimating, modalInfo, currentPlayer]);

    // Effect to automate all AI actions during combat
    useEffect(() => {
        if (!currentPlayer || currentPlayer.controller !== 'ai' || !gameState.combatState.active || isAnimating) {
            return;
        }

        const { combatPhase, attacksMadeThisTurn } = gameState.combatState;
        let actionTimeout: ReturnType<typeof setTimeout>;

        if (combatPhase === 'initial' || combatPhase === 'round_over') {
            actionTimeout = setTimeout(() => {
                const enemy = gameState.enemies.find(e => e.id === gameState.combatState.enemyId);
                if (attacksMadeThisTurn < 3 && enemy && enemy.hp > 0) {
                    handleStartAttackRolls();
                } else {
                    handleEndCombatTurn();
                }
            }, AI_THINK_DELAY);
        } else if (combatPhase === 'attack_rolls') {
             actionTimeout = setTimeout(() => handleStartDefenseRolls(), 1800);
        } else if (combatPhase === 'defense_rolls') {
             actionTimeout = setTimeout(() => handleApplyCombatResults(), 1800);
        } else if (combatPhase === 'results_display') {
            actionTimeout = setTimeout(() => handleResolveCombatRound(), 2000);
        } 
        return () => { if (actionTimeout) clearTimeout(actionTimeout); };
    }, [gameState.combatState, gameState.currentPlayerIndex, isAnimating, currentPlayer]);


    // Effect to show Dice Upgrade Modal
    useEffect(() => {
        const player = gameState.players[gameState.currentPlayerIndex];
        if (player && player.pendingUpgrades > 0 && !isUpgradeModalOpen && player.controller === 'human') {
            setIsUpgradeModalOpen(true);
        } else if ((!player || player.pendingUpgrades === 0) && isUpgradeModalOpen) {
            setIsUpgradeModalOpen(false);
        }
    }, [gameState.players, gameState.currentPlayerIndex, isUpgradeModalOpen]);


    // Effect for Toast
    useEffect(() => {
        if (toastInfo) {
            const timer = setTimeout(() => {
                setToastInfo(null);
            }, 3900);
            return () => clearTimeout(timer);
        }
    }, [toastInfo]);

    // Effect for Key Award Notifications
    useEffect(() => {
        const previousKeys = previousKeysRef.current;
        const newlyAwardedKeys = (Object.keys(gameState.keys) as KeyColor[]).filter(
            key => gameState.keys[key] && !previousKeys[key]
        );

        if (newlyAwardedKeys.length > 0) {
            const keyColor = newlyAwardedKeys[0];
            const player = gameState.players.find(p => p.color === keyColor);
            const keyNameMapping: Record<KeyColor, string> = { red: 'Rossa', yellow: 'Gialla', white: 'Bianca', black: 'Nera' };
            const keyName = keyNameMapping[keyColor];
            setToastInfo({ message: `${player?.name || 'La squadra'} ha ottenuto la Chiave ${keyName}!`, id: Date.now() });
        }

        previousKeysRef.current = gameState.keys;
    }, [gameState.keys, gameState.players]);

    // Effect for Trust Level Notifications
    useEffect(() => {
        const oldLevel = previousTrustLevelRef.current;
        const newLevel = gameState.trustLevel;

        if (newLevel !== oldLevel) {
            const trustData: Record<string, string> = {
                ostili: 'Ostili',
                diffidenti: 'Diffidenti',
                neutrale: 'Neutrale',
                amichevole: 'Amichevole',
                alleato: 'Alleato',
            };
            setToastInfo({ message: `Livello Fiducia cambiato in: ${trustData[newLevel]}!`, id: Date.now() });
        }

        previousTrustLevelRef.current = newLevel;
    }, [gameState.trustLevel]);


  // --- Context Menu Actions ---
  const handleEquipWeapon = (playerId: number, inventoryIndex: number) => {
    setGameState(gs => gameEngine.equipWeapon(gs, playerId, inventoryIndex));
    setContextMenuInfo(null);
  };

  const handleUnequipWeapon = (playerId: number) => {
    setGameState(gs => gameEngine.unequipWeapon(gs, playerId));
    setContextMenuInfo(null);
  };

  const handleDropWeapon = (playerId: number, inventoryIndex: number) => {
    setGameState(gs => gameEngine.dropWeapon(gs, playerId, inventoryIndex));
    setContextMenuInfo(null);
  };

  const handleDropEquippedWeapon = (playerId: number) => {
    setGameState(gs => gameEngine.dropEquippedWeapon(gs, playerId));
    setContextMenuInfo(null);
  };

  const openContextMenu = (e: React.MouseEvent, options: ContextMenuProps['options']) => {
    e.preventDefault();
    e.stopPropagation();
    const boundClose = () => setContextMenuInfo(null);
    options.forEach(opt => {
        const originalAction = opt.action;
        opt.action = () => {
            originalAction();
            boundClose(); // Close menu after action
        };
    });
    setContextMenuInfo({ x: e.clientX, y: e.clientY, options, onClose: boundClose });
  };

  // --- Main Render ---
  const handleRestart = () => {
    window.location.reload();
  };

  const TrustDisplay: React.FC<{ trust: number; trustLevel: string }> = ({ trust, trustLevel }) => {
    const trustData: Record<string, { icon: string; title: string; description: string }> = {
        ostili: { icon: '😠', title: 'Ostili', description: 'Le entità del sogno sono ostili. I prezzi sono più alti e le ricompense minori.' },
        diffidenti: { icon: '😒', title: 'Diffidenti', description: 'La tua reputazione è bassa. I mercanti sono sospettosi e i PNG meno generosi.' },
        neutrale: { icon: '😐', title: 'Neutrale', description: 'La tua reputazione nel mondo onirico è neutrale.' },
        amichevole: { icon: '😊', title: 'Amichevole', description: 'Sei visto con favore. Ottieni sconti e ricompense migliori.' },
        alleato: { icon: '😇', title: 'Alleato', description: 'Sei un faro di speranza. Gli abitanti del sogno si fidano ciecamente di te.' },
    };

    const data = trustData[trustLevel] || trustData.neutrale;

    return (
        <div className="trust-display-container" title={`${data.description} (Punteggio: ${trust})`}>
            <div className="trust-icon">{data.icon}</div>
            <div className="trust-info">
                <h4>Fiducia: {data.title}</h4>
                <small>La reputazione della squadra.</small>
            </div>
        </div>
    );
  };

  const renderModal = () => {
    if (!modalInfo) return null;

    let content: React.ReactNode = null;
    let footer: React.ReactNode = null;

    // Modals that require a specific user action and should not be closed by clicking the overlay.
    const isActionRequiredModal = [
        'treasure_reveal',
        'special_square_reveal',
        'swap_confirmation',
        'loot_choice',
        'quest_offer',
        'enemy_encounter',
        'titan_encounter',
        'combat',
        'mage_encounter',
        'dialogue',
        'choose_enemy_type_for_spell',
        'hp_sacrifice_choice',
        'copy_spell_prompt'
    ].includes(modalInfo.type);

    switch (modalInfo.type) {
        case 'info':
            content = <InfoModalContent modalInfo={modalInfo} />;
            const handleInfoClick = () => {
                if (modalInfo.title === 'Vittoria!' || modalInfo.title === 'Game Over') {
                    handleRestart();
                } else if (modalInfo.title === 'Fuga Fallita!' && modalInfo.enemy) {
                    handleChooseToFight(modalInfo.enemy as Enemy, modalInfo.hasPlayerMoved ?? false);
                } else if ((modalInfo.title === 'Dialogo Fallito!' || modalInfo.title === 'Dialogo Fallito') && modalInfo.enemy) {
                    // CRITICAL CHANGE: Transition directly to combat on failure acknowledgment
                    handleChooseToFight(modalInfo.enemy as Enemy, modalInfo.hasPlayerMoved ?? true);
                }
                else {
                    closeModal();
                }
            };
            footer = <button onClick={handleInfoClick} className="modal-action-button">OK</button>;
            break;
        case 'loot_choice':
            content = <LootModalContent modalInfo={modalInfo} onLootItemSelect={handleLootItemSelect} />;
            const hasItems = modalInfo.items && modalInfo.items.length > 0;
            footer = (<>
                <button onClick={closeModal} className="modal-action-button">{hasItems ? 'Ignora Oggetti' : 'Chiudi'}</button>
                {hasItems && <button onClick={handleLootAll} className="modal-action-button confirm">Raccogli tutto</button>}
            </>);
            break;
        case 'swap_confirmation':
            content = <SwapConfirmationModalContent modalInfo={modalInfo} />;
            footer = (<>
                <button onClick={() => handleSwapConfirm(modalInfo.targetItemId)} className="modal-action-button confirm">Sostituisci</button>
                <button onClick={closeModal} className="modal-action-button">Annulla</button>
            </>);
            break;
        case 'treasure_reveal': {
            const handleOpenTreasure = () => {
                setModalInfo({
                    type: 'info',
                    title: modalInfo.title,
                    message: modalInfo.message
                });
            };
            content = (
                <div className="treasure-reveal-content">
                    <p>Hai trovato un tesoro!</p>
                    <img 
                        src={preloadedAssets.items.treasureChestClosed} 
                        alt="Scrigno del tesoro" 
                        className="treasure-chest-image"
                        onClick={handleOpenTreasure}
                    />
                </div>
            );
            footer = <button onClick={handleOpenTreasure} className="modal-action-button confirm">Apri</button>;
            break;
        }
        case 'special_square_reveal': {
            content = (
                <SpecialSquareCardContent 
                    squareType={modalInfo.squareType}
                    message={modalInfo.message}
                    onClose={closeModal}
                />
            );
            footer = null;
            break;
        }
        case 'titan_encounter':
            content = <InfoModalContent modalInfo={modalInfo} />;
            footer = (<button onClick={handleEngageTitan} className="modal-action-button confirm">Entra in Risonanza</button>);
            break;
        case 'enemy_encounter': {
            const encounterEnemy = modalInfo.enemy;
            const hasPlayerMoved = modalInfo.hasPlayerMoved;
            const isMage = currentPlayer.class === 'mago';
            const handleForcedFight = () => {
                handleChooseToFight(encounterEnemy, hasPlayerMoved);
                setModalInfo(null);
            };

            content = <EnemyEncounterModalContent modalInfo={modalInfo} gameState={gameState} />;
            footer = (<>
                {modalInfo.dialogueRefused ? (
                    <>
                        {!hasPlayerMoved && <button onClick={() => handleFlee(hasPlayerMoved)} className="modal-action-button">Fuggi</button>}
                        <button onClick={handleForcedFight} className="modal-action-button confirm">Entra in Risonanza</button>
                    </>
                ) : (
                    <>
                        {!hasPlayerMoved && <button onClick={() => handleFlee(hasPlayerMoved)} className="modal-action-button">Fuggi</button>}
                        {gameState.gameMode === 'online' && (
                            <button onClick={() => handleChooseToTalk(encounterEnemy, hasPlayerMoved)} className="modal-action-button">Parla</button>
                        )}
                        <button onClick={handleChooseToFight(encounterEnemy, hasPlayerMoved)} className="modal-action-button confirm">Entra in Risonanza</button>
                    </>
                )}
                {isMage && hasPlayerMoved && <button onClick={closeModal} className="modal-action-button">Prosegui</button>}
            </>);
            break;
        }
        case 'dialogue':
            content = <DialogueModalContent modalInfo={modalInfo} setGameState={setGameState} setModalInfo={setModalInfo} onChoice={handleDialogueChoice} onDialogueFail={handleDialogueFailure} trustLevel={gameState.trustLevel} />;
            // Footer is managed inside the component
            break;
        case 'combat':
        case 'mage_encounter':
            content = <CombatModalContent gameState={gameState} modalInfo={modalInfo} currentPlayerColor={playerColorHex[currentPlayer.color]} />;
            const { combatPhase, attacksMadeThisTurn } = gameState.combatState;
            const maxAttacks = 3;
            if (modalInfo.type === 'mage_encounter' && combatPhase === 'initial') {
                footer = (<>
                    <button onClick={handleEndCombatTurn} className="modal-action-button">Prosegui</button>
                    <button onClick={handleStartAttackRolls} className="modal-action-button confirm">Attacca</button>
                </>);
            } else {
                 switch (combatPhase) {
                    case 'initial': footer = (<button onClick={handleStartAttackRolls} className="modal-action-button confirm">Attacca</button>); break;
                    case 'attack_rolls': footer = <button onClick={handleStartDefenseRolls} className="modal-action-button">Lancia Difesa</button>; break;
                    case 'defense_rolls': footer = <button onClick={handleApplyCombatResults} className="modal-action-button">Mostra Risultati</button>; break;
                    case 'results_display': footer = <button onClick={handleResolveCombatRound} className="modal-action-button confirm">Continua</button>; break;
                    case 'round_over':
                        if (attacksMadeThisTurn < maxAttacks) {
                            footer = (<><button onClick={handleEndCombatTurn} className="modal-action-button">Termina Turno</button><button onClick={handleStartAttackRolls} className="modal-action-button confirm">Attacca di nuovo</button></>);
                        } else {
                            footer = <button onClick={handleEndCombatTurn} className="modal-action-button">Termina Turno</button>;
                        }
                        break;
                }
            }
            break;
        case 'merchant':
            content = <MerchantModalContent modalInfo={modalInfo} gameState={gameState} onPurchaseItem={handlePurchaseItem} />;
            footer = <button onClick={closeModal} className="modal-action-button">Vattene</button>;
            break;
        case 'shared_stash':
            content = <StashModalContent gameState={gameState} openContextMenu={openContextMenu} onDepositItem={handleDepositItem} onWithdrawItem={handleWithdrawItem} onMoveItem={handleMoveItem} />;
            footer = <button onClick={closeModal} className="modal-action-button">Chiudi</button>;
            break;
        case 'quest_offer':
             const npc = modalInfo.npc;
             const canComplete = currentPlayer.inventory.some(item => item?.type === 'questItem' && item.name === npc.quest.requiredItemName) && currentPlayer.activeQuestId === npc.quest.id;
             content = (
                <QuestModalContent 
                    modalInfo={modalInfo} 
                    gameState={gameState}
                    setGameState={setGameState}
                />
            );
             footer = (<>
                <button onClick={closeModal} className="modal-action-button">Rifiuta</button>
                <button 
                    onClick={() => handleAcceptQuest(npc.id)} 
                    className="modal-action-button confirm"
                    disabled={npc.quest.id === 'PENDING_GENERATION'}
                >
                    {canComplete ? "Completa Missione" : "Accetta"}
                </button>
            </>);
            break;
        case 'hp_sacrifice_choice':
            content = <HPSacrificeModalContent maxHP={currentPlayer.hp} onSacrifice={handleHPSacrifice} />;
            footer = <button onClick={closeModal} className="modal-action-button">Annulla</button>;
            break;
        case 'choose_enemy_type_for_spell':
            content = <RevealTypeModalContent onSelect={handleRevealTypeChoice} />;
            footer = <button onClick={closeModal} className="modal-action-button">Annulla</button>;
            break;
        case 'copy_spell_prompt':
            content = <CopySpellModalContent modalInfo={modalInfo} />;
            footer = (
                <>
                    <button onClick={() => handleCopySpellChoice(false)} className="modal-action-button">No</button>
                    <button onClick={() => handleCopySpellChoice(true)} className="modal-action-button confirm">Sì</button>
                </>
            );
            break;
    }

    const finalOnClose = isActionRequiredModal ? () => {} : closeModal;

    return (
        <ModalWrapper title={modalInfo.title} onClose={finalOnClose} footerContent={footer} isClosing={isModalClosing}>
            {content}
        </ModalWrapper>
    );
};


  return (
    <>
      {view === 'splash' && <SplashScreen onStart={handleSplashClick} />}
      {view === 'selection' && <SelectionScreen onSettingsConfirm={handleSettingsConfirm} />}
      {view === 'loading' && <LoadingScreen />}

      {view === 'game' && (
        <div className={`app-container ${view === 'game' ? 'game-fade-in' : ''}`}>
          <div className="game-area">
            <div className="game-board">
                <svg
                    className={`game-board-svg ${isGameReady ? 'animations-enabled' : ''}`}
                    viewBox={`-${PADDING} -${PADDING} ${viewBoxWidth} ${viewBoxHeight}`}
                    preserveAspectRatio="xMidYMid meet"
                >
                    <defs>
                      <clipPath id="rounded-board-mask">
                        <rect x={`-${PADDING}`} y={`-${PADDING}`} width={viewBoxWidth} height={viewBoxHeight} rx="8" ry="8" />
                      </clipPath>
                    </defs>
                    <image href={preloadedAssets.backgrounds.gameBoard} x={`-${PADDING}`} y={`-${PADDING}`} width={viewBoxWidth} height={viewBoxHeight} preserveAspectRatio="xMidYMid slice" clipPath="url(#rounded-board-mask)" />
                    {allCells.map((cell, index) => {
                        const isGate = Object.values(gameEngine.GATE_CELLS).includes(cell.id!);
                        let gateColor: gameEngine.KeyColor | undefined;
                        if (isGate) {
                            gateColor = (Object.keys(gameEngine.GATE_CELLS) as gameEngine.KeyColor[]).find(key => gameEngine.GATE_CELLS[key] === cell.id);
                        }
                        const isGateOpen = gateColor ? gameState.gates[`${gateColor}Open`] : true;
                        const isCorner = Object.values(PLAYER_START_POSITIONS).includes(cell.id!);
                        const cellStyle: React.CSSProperties = { fill: cell.fillColor || 'var(--cell-fill-color)' };
                        if (cell.fillOpacity !== undefined) cellStyle.fillOpacity = cell.fillOpacity;
                        if (cell.strokeColor) cellStyle.stroke = cell.strokeColor;
                        if (cell.strokeOpacity !== undefined) cellStyle.strokeOpacity = cell.strokeOpacity;
                        return (
                          <rect key={`cell-${index}`} x={cell.x} y={cell.y} width={cell.width} height={cell.height} rx="5"
                              className={`cell-svg ${!isGateOpen ? 'gate-closed' : ''} ${isCorner ? 'corner-cell' : ''} ${gameState.gameStatePhase === 'cell_inspection' || gameState.gameStatePhase === 'spell_target_cell' || gameState.gameStatePhase === 'spell_target_enemy' ? 'clickable' : ''}`}
                              style={cellStyle} onClick={() => handleCellClick(cell.id)}
