// Add stash functions required by index.tsx
export const depositToStash = (gs: GameState, inventoryIndex: number): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const item = p.inventory.splice(inventoryIndex, 1)[0];
    const emptySlotIdx = ns.sharedStash.indexOf(null);
    if (emptySlotIdx !== -1) {
        ns.sharedStash[emptySlotIdx] = item;
    } else {
        ns.sharedStash.push(item);
    }
    return updateCurrentGameState(ns);
};

export const withdrawFromStash = (gs: GameState, stashIndex: number): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    if (p.inventory.length < p.inventorySize) {
        const item = ns.sharedStash[stashIndex];
        if (item) {
            p.inventory.push(item);
            ns.sharedStash[stashIndex] = null;
        }
    }
    return updateCurrentGameState(ns);
};

export const moveItem = (gs: GameState, source: ItemLocation, destination: ItemLocation): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];

    let item: InventoryItem | null = null;

    // Get item from source
    if (source.area === 'player_inventory') {
        item = p.inventory.splice(source.slot as number, 1)[0];
    } else if (source.area === 'player_equipped') {
        item = p.equippedWeapon;
        p.equippedWeapon = null;
        p.attackDice = [];
    } else if (source.area === 'stash') {
        item = ns.sharedStash[source.slot as number];
        ns.sharedStash[source.slot as number] = null;
    }

    if (!item) return gs;

    // Place item in destination
    if (destination.area === 'player_inventory') {
        p.inventory.push(item);
    } else if (destination.area === 'player_equipped') {
        if (item.type === 'melee' || item.type === 'ranged' || item.type === 'magic') {
            const oldEquipped = p.equippedWeapon;
            p.equippedWeapon = item as Weapon;
            p.attackDice = Array.from({ length: p.equippedWeapon.damageDice }, (_, i) => ({ id: i, hits: 2, bonusHits: 0, hasCrit: false }));
            if (oldEquipped) p.inventory.push(oldEquipped);
        } else {
            p.inventory.push(item);
        }
    } else if (destination.area === 'stash') {
        const targetIdx = destination.slot as number;
        const oldStashItem = ns.sharedStash[targetIdx];
        ns.sharedStash[targetIdx] = item;
        if (oldStashItem) {
             if (source.area === 'player_inventory') p.inventory.push(oldStashItem);
             else {
                 const firstEmpty = ns.sharedStash.indexOf(null);
                 if (firstEmpty !== -1) ns.sharedStash[firstEmpty] = oldStashItem;
             }
        }
    }

    return updateCurrentGameState(ns);
};

