export const isMoveValid = (gs: GameState, cid: number) => gs.gameStatePhase === 'moving' ? (gs.reachableCells?.includes(cid) || false) : true;
export const pickUpWorldItem = (gs: GameState, id: string): { newState: GameState, modalInfo: ModalInfo | null } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const idx = ns.worldItems.findIndex((w: WorldItem) => w.id === id);
    if (idx !== -1) {
        p.inventory.push(ns.worldItems.splice(idx, 1)[0].item);
    }
    return { newState: updateCurrentGameState(ns), modalInfo: null };
};
export const pickUpAllLoot = (gs: GameState): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const items = ns.worldItems.filter((w: WorldItem) => w.position === p.position);
    items.forEach((i: WorldItem) => p.inventory.push(i.item));
    ns.worldItems = ns.worldItems.filter((w: WorldItem) => w.position !== p.position);
    return updateCurrentGameState(ns);
};

export const equipWeapon = (gs: GameState, pid: number, idx: number): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    const old = p.equippedWeapon;
    p.equippedWeapon = p.inventory.splice(idx, 1)[0] as Weapon;
    if (old) p.inventory.push(old);
    p.attackDice = Array.from({ length: p.equippedWeapon.damageDice }, (_, i) => ({ id: i, hits: 2, bonusHits: 0, hasCrit: false }));
    return updateCurrentGameState(ns);
};

export const unequipWeapon = (gs: GameState, pid: number): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    if (p.equippedWeapon) p.inventory.push(p.equippedWeapon);
    p.equippedWeapon = null; p.attackDice = [];
    return updateCurrentGameState(ns);
};

export const dropWeapon = (gs: GameState, pid: number, idx: number): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    const item = p.inventory.splice(idx, 1)[0];
    ns.worldItems.push({ id: `drop_${Date.now()}`, name: item.name, position: p.position, isVisible: true, pawnImage: preloadedAssets.items.weaponOnMap, item });
    return updateCurrentGameState(ns);
};

export const dropEquippedWeapon = (gs: GameState, pid: number): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    if (!p.equippedWeapon) return gs;
    const item = p.equippedWeapon; p.equippedWeapon = null; p.attackDice = [];
    ns.worldItems.push({ id: `drop_${Date.now()}`, name: item.name, position: p.position, isVisible: true, pawnImage: preloadedAssets.items.weaponOnMap, item });
    return updateCurrentGameState(ns);
};

export const useConsumable = (gs: GameState, pid: number, idx: number): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    const item = p.inventory.splice(idx, 1)[0] as Consumable;
    if (item.effectTag === 'heal') p.hp = Math.min(p.maxHp, p.hp + item.value);
    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Usato', message: `Usato ${item.name}` } as ModalInfo };
};

export const purchaseItemFromMerchant = (gs: GameState, item: any, mid: number): { newState: GameState, success: boolean, message: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const cost = item.type === 'intention' ? item.costToBuy : (item.costsByLevel ? item.costsByLevel[item.level - 1] : item.cost);
    if (p.coins < cost) return { newState: gs, success: false, message: 'Intento insufficiente.' };
    p.coins -= cost;
    if (item.type === 'intention') p.spells.push(item); else p.inventory.push(item);
    return { newState: updateCurrentGameState(ns), success: true, message: 'Acquistato!' };
};

export const acceptQuest = (gs: GameState, nid: number): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const npc = ns.npcs.find((n: NPC) => n.id === nid)!;
    p.activeQuestId = npc.quest.id;
    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: 'Accettata', message: 'Missione avviata.' } as ModalInfo };
};

export const applyDiceUpgrade = (gs: GameState, type: 'attack' | 'defense', did: number, utype: string): GameState => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const die = (type === 'attack' ? p.attackDice : p.defenseDice).find(d => d.id === did)!;
    if (utype === 'add_hit') die.hits++; else die.hasCrit = true;
    p.pendingUpgrades--;
    return updateCurrentGameState(ns);
};

export const calculateAIMove = (gs: GameState): AIAction => {
    const p = gs.players[gs.currentPlayerIndex];
    const reachable = gs.reachableCells || [];
    if (reachable.length > 0) return { type: 'move', targetCellId: reachable[getRandomInt(0, reachable.length - 1)] };
    return { type: 'end_turn' };
};

