let _boardAdjacency: Record<number, number[]> | null = null;
const getBoardAdjacency = (): Record<number, number[]> => {
    if (_boardAdjacency) return _boardAdjacency;
    const adj: Record<number, number[]> = {};
    const allCellIds = initialBoardLayout.allCells.map(c => c.id).filter(Boolean) as number[];
    for (const id of allCellIds) adj[id] = [];
    for (let i = 1; i <= 48; i++) {
        const next = (i === 48) ? 1 : i + 1;
        const prev = (i === 1) ? 48 : i - 1;
        adj[i].push(prev, next);
    }
    adj[40].push(68); adj[68].push(40); adj[16].push(58); adj[58].push(16); adj[25].push(67); adj[67].push(25); adj[1].push(49); adj[49].push(1);
    [[68, 65], [65, 62], [62, 59], [59, 69], [58, 51], [51, 52], [52, 53], [53, 54], [54, 69], [67, 56], [56, 60], [60, 61], [61, 63], [63, 64], [64, 69], [49, 50], [50, 55], [55, 57], [57, 66], [66, 69]].forEach(([from, to]) => { adj[from].push(to); adj[to].push(from); });
    _boardAdjacency = adj;
    return adj;
};

export const findShortestPath = (startId: number, endId: number, gates: GameState['gates']): number[] | null => {
    if (startId === endId) return [startId];
    const boardAdjacency = getBoardAdjacency();
    const queue: { cell: number, path: number[] }[] = [{ cell: startId, path: [startId] }];
    const visited = new Set<number>([startId]);
    while (queue.length > 0) {
        const { cell, path } = queue.shift()!;
        if (cell === endId) return path;
        for (const neighbor of boardAdjacency[cell] || []) {
            if (!visited.has(neighbor)) {
                const isCrossingGate = (Object.values(GATE_CELLS).includes(cell) && !Object.values(GATE_CELLS).includes(neighbor)) || (Object.values(GATE_CELLS).includes(neighbor) && !Object.values(GATE_CELLS).includes(cell));
                if(isCrossingGate) {
                    const gateCell = Object.values(GATE_CELLS).includes(cell) ? cell : neighbor;
                    const gateColor = (Object.keys(GATE_CELLS) as KeyColor[]).find(key => GATE_CELLS[key] === gateCell);
                    if (gateColor && !gates[`${gateColor}Open` as keyof GameState['gates']]) continue;
                }
                visited.add(neighbor);
                queue.push({ cell: neighbor, path: [...path, neighbor] });
            }
        }
    }
    return null;
};

const calculateDistance = (startId: number, endId: number, gates: GameState['gates']): number => {
    const path = findShortestPath(startId, endId, gates);
    return path ? path.length - 1 : Infinity;
};

