export const rollDice = (gs: GameState): { newState: GameState, roll: number } => {
    let roll = getRandomInt(1, 6);
    const p = gs.players[gs.currentPlayerIndex];
    if (p.nextRollHalved) { roll = Math.max(1, Math.floor(roll / 2)); p.nextRollHalved = undefined; }
    const ns = { ...JSON.parse(JSON.stringify(gs)), diceResult: roll, gameStatePhase: 'moving' as GamePhase };
    ns.reachableCells = calculateReachableCells(ns);
    return { newState: updateCurrentGameState(ns), roll };
};

const calculateReachableCells = (gs: GameState): number[] => {
    const p = gs.players[gs.currentPlayerIndex];
    const roll = gs.diceResult;
    if (roll === 0) return [];
    const adj = getBoardAdjacency();
    const queue = [{ cell: p.position, dist: 0 }];
    const visited = new Map([[p.position, 0]]);
    const reachable = new Set<number>();
    while (queue.length > 0) {
        const { cell, dist } = queue.shift()!;
        if (dist > 0 && !gs.players.some(op => op.id !== p.id && op.position === cell && !op.isDead)) reachable.add(cell);
        if (dist >= roll) continue;
        for (const neighbor of adj[cell] || []) {
            const isCrossingGate = (Object.values(GATE_CELLS).includes(cell) && !Object.values(GATE_CELLS).includes(neighbor)) || (Object.values(GATE_CELLS).includes(neighbor) && !Object.values(GATE_CELLS).includes(cell));
            if(isCrossingGate) {
                const gc = (Object.keys(GATE_CELLS) as KeyColor[]).find(k => GATE_CELLS[k] === (Object.values(GATE_CELLS).includes(cell) ? cell : neighbor));
                if (gc && !gs.gates[`${gc}Open` as keyof GameState['gates']]) continue;
            }
            if (!visited.has(neighbor) || visited.get(neighbor)! > dist + 1) { visited.set(neighbor, dist + 1); queue.push({ cell: neighbor, dist: dist + 1 }); }
        }
    }
    return Array.from(reachable);
};

export const movePlayerAndResolveLanding = (gs: GameState, targetCellId: number): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string, levelUpInfo: any } => {
    let ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const oldPos = p.position;
    const oldLevel = p.level;
    p.position = targetCellId; ns.diceResult = 0; ns.reachableCells = null;

    // Level Up Check
    const startPos = PLAYER_START_POSITIONS[p.id];
    if (oldPos < startPos && targetCellId >= startPos) {
        p.level++; p.maxHp += 5; p.hp = p.maxHp; p.toughness++;
        p.defenseDice.push({ id: p.defenseDice.length, hits: 2, bonusHits: 0, hasCrit: false });

        // AUTO-LEARN MAGIC
        const spellIndex = Math.floor(p.level / 2) - 1;
        if (p.level % 2 === 0 && spellIndex >= 0 && spellIndex < allMagicSpells.length) {
            const spellTemplate = allMagicSpells[spellIndex];
            if (!p.spells.some(s => s.name === spellTemplate.name)) {
                p.spells.push({ ...spellTemplate, id: `${spellTemplate.name.replace(/\s/g, '')}_${Date.now()}` });
            }
        }
    }

    const enemy = ns.enemies.find((e: Enemy) => e.position === targetCellId);
    if (enemy) return { newState: updateCurrentGameState(ns), modalInfo: { type: 'enemy_encounter', title: 'Incontro Ostile!', enemy, dialogueRefused: Math.random() < 0.2, hasPlayerMoved: true }, levelUpInfo: null };

    ns.gameStatePhase = 'end_turn';
    return { newState: updateCurrentGameState(ns), modalInfo: null, levelUpInfo: null };
};

// --- SPELL LOGIC ---
export const castSpell = (gs: GameState, pid: number, sid: string): { newState: GameState, modalInfo: ModalInfo | null, audioAnnouncement?: string } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players.find((pl: Player) => pl.id === pid)!;
    const spell = p.spells.find((s: MagicSpell) => s.id === sid);
    if (!spell) return { newState: gs, modalInfo: null };
    if (p.coins < spell.costToUse) return { newState: gs, modalInfo: { type: 'info', title: 'Intento Insufficiente', message: 'Non hai abbastanza Intento.' } };

    if (spell.effectTag === 'reveal_enemy_pain' || spell.effectTag === 'teleport') {
        p.castingSpellId = sid;
        ns.gameStatePhase = spell.effectTag === 'teleport' ? 'spell_target_cell' : 'spell_target_enemy';
        return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: spell.name, message: 'Seleziona il bersaglio sulla mappa.' } };
    }

    p.coins -= spell.costToUse;
    p.hasCastSpellThisTurn = true;

    if (spell.effectTag === 'reveal_quest_item') {
        const q = offlineQuests.find(q => q.id === p.activeQuestId);
        if (q) {
            const t = ns.treasures.find((tr: Treasure) => tr.itemName === q.requiredItemName);
            if (t) { t.isVisible = true; t.visibleUntilTurn = ns.turnNumber + 3; }
        }
    } else if (spell.effectTag === 'reveal_enemy_type') {
        return { newState: gs, modalInfo: { type: 'choose_enemy_type_for_spell', title: 'Scegli Tipo', spellId: sid } };
    }

    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: spell.name, message: 'Intenzione lanciata!' } };
};

export const applySpellEffectToTarget = (gs: GameState, tid: number): { newState: GameState, modalInfo: ModalInfo | null } => {
    const ns = JSON.parse(JSON.stringify(gs));
    const p = ns.players[ns.currentPlayerIndex];
    const spell = p.spells.find((s: MagicSpell) => s.id === p.castingSpellId);
    if (!spell) return { newState: gs, modalInfo: null };

    p.coins -= spell.costToUse;
    p.castingSpellId = undefined;
    p.hasCastSpellThisTurn = true;
    ns.gameStatePhase = 'end_turn';

    if (spell.effectTag === 'teleport') {
        p.position = tid;
    } else if (spell.effectTag === 'reveal_enemy_pain') {
        const e = ns.enemies.find((en: Enemy) => en.position === tid);
        if (e) e.painRevealed = true;
    }

    return { newState: updateCurrentGameState(ns), modalInfo: { type: 'info', title: spell.name, message: 'Effetto applicato.' } };
};

