            enemiesDefeatedCount: 0, keyQuestProgress: 0, hasSpawnedMiniBoss: false, activeQuestId: null,
            activeQuestHint: null, farthestCellReached: PLAYER_START_POSITIONS[i + 1], pendingUpgrades: 0,
            attackDice: [], defenseDice: [{ id: 0, hits: 2, bonusHits: 0, hasCrit: false }],
        };
        p.attackDice = Array.from({ length: p.equippedWeapon!.damageDice }, (_, j) => ({ id: j, hits: 2, bonusHits: 0, hasCrit: false }));
