import React, { useState, useEffect } from 'react';
import { Enemy } from '../../gameLogic';

interface DialogueModalContentProps {
    enemy: Enemy;
    trustLevel: string;
    onClose: () => void;
}

export const DialogueModalContent: React.FC<DialogueModalContentProps> = ({ enemy, trustLevel, onClose }) => {
    const [rapportScore, setRapportScore] = useState(0);

    // Initial effect to calculate rapport and setup dialogue
    useEffect(() => {
        const initDialogue = async () => {
             // Set initial rapport based on trust
            let initialRapport = 0;
            switch(trustLevel) {
                case 'amichevole': initialRapport = 1; break;
                case 'alleato': initialRapport = 2; break;
                case 'diffidenti': initialRapport = -1; break;
                case 'ostili': initialRapport = -2; break;
                default: initialRapport = 0; break;
            }

            // NUOVO: Bonus Percezione se l'incubo è stato analizzato
            if (enemy.painRevealed) {
                initialRapport += 2;
            }

            setRapportScore(initialRapport);
            // ... (resto della funzione initDialogue identico)
        };
        initDialogue();
    }, [enemy, trustLevel]);

    return (
        <div className="dialogue-modal-content">
            <h3>Dialogo con {enemy.name}</h3>
            <p>Rapporto: {rapportScore}</p>
            {/* ... resto della UI ... */}
            <button onClick={onClose}>Esci</button>
        </div>
    );
};
